window.VOCAB_CLASSROOM = [{"id":"praeteritum","number":1,"added":"2026-11-07","level":"B1.1","title":"Präteritum","title_en":"Czas przeszły Präteritum: do opowiadań i relacji","summary":"Opisz na piśmie, co się wydarzyło (*Der Zug kam um 8 Uhr an.*): czasowniki regularne z *-te*, nieregularne z nowym tematem i dlaczego Szwajcarzy prawie nigdy go nie używają w mowie.","purpose":["Präteritum to **prosty czas przeszły**: jedno słowo, bez czasownika posiłkowego. *Ich **ging** nach Hause.* (Poszedłem do domu.) Znaczy to samo co Perfekt (*Ich **bin** nach Hause **gegangen***). Różnica dotyczy głównie tego, **gdzie** go używasz.","Potrzebujesz go do **czytania i pisania**: opowiadań, relacji, artykułów prasowych, CV, e-maila o tym, co się wydarzyło. W **rozmowie** większość ludzi używa czasu Perfekt, z wyjątkiem *war*, *hatte* i czasowników modalnych (*konnte, musste, wollte* …), które są częste także w mowie."],"logic":["Trzy rodzaje czasowników, trzy wzorce: czasowniki **regularne** dodają *-te* (*machen → machte*), **nieregularne** zmieniają temat (*gehen → ging*), a **mieszane** robią jedno i drugie (*denken → dachte*).","**ich** i **er / sie / es** mają tę samą formę, **bez końcówki**: *ich ging, er ging*; *ich machte, sie machte*.","Pozostałe osoby dodają końcówki *du -(e)st, wir -(e)n, ihr -(e)t, sie / Sie -(e)n*: *du gingst, wir gingen*; *du machtest, wir machten*. Czasowniki mocne, których temat kończy się na *-t* lub *-d*, dodają *e*: *du fandest, ihr fandet*.","Każdego czasownika nieregularnego ucz się z jego trzema formami: *gehen – ging – gegangen*. Tematu Präteritum nie da się wywnioskować z bezokolicznika.","Niemieckie czasy nie wyrażają aspektu. Präteritum to **nie** włoskie *imperfetto*, francuskie *imparfait* ani hiszpańskie *imperfecto*: używa się go także do pojedynczych, zakończonych zdarzeń (*Der Zug **kam** um 8 Uhr **an**.*).","W rozmowie przy większości czasowników używaj czasu Perfekt. *war*, *hatte* i czasowniki modalne (*konnte, musste, wollte* …) są w Präteritum normalne także w mowie: *Ich **war** krank und **konnte** nicht kommen.*"],"rules":[{"title":"Czasowniki regularne: temat + -te","text":"Weź temat (*machen → mach-*) i dodaj **-te** oraz końcówkę. Jeśli temat kończy się na **-d** lub **-t**, dodaj **-ete**, żeby dało się to wymówić: *arbeiten → arbeitete*, *reden → redete*.","table":{"caption":"Präteritum czasowników regularnych","head":["","machen","arbeiten"],"rows":[["ich","**machte**","**arbeitete**"],["du","machtest","arbeitetest"],["er / sie / es","**machte**","**arbeitete**"],["wir","machten","arbeiteten"],["ihr","machtet","arbeitetet"],["sie / Sie","machten","arbeiteten"]]},"examples":[{"de":"Früher **wohnte** ich in Basel.","en":"Kiedyś mieszkałem w Bazylei."},{"de":"Der Techniker **reparierte** den Drucker in zehn Minuten.","en":"Technik naprawił drukarkę w dziesięć minut."},{"de":"Wir **warteten** eine halbe Stunde auf das Tram.","en":"Czekaliśmy pół godziny na tramwaj.","note":"*warten* kończy się na *-t*, więc *-ete-*."}],"source":"schwach"},{"title":"Czasowniki nieregularne: nowy temat, bez końcówki dla ich i er","text":"Czasowniki nieregularne (mocne) zmieniają samogłoskę tematu i **nie dostają -te**. *ich* i *er / sie / es* **nic** nie dodają do nowego tematu; pozostałe osoby mają zwykłe końcówki.","table":{"caption":"Präteritum czasowników nieregularnych","head":["","gehen","kommen","fahren"],"rows":[["ich","**ging**","**kam**","**fuhr**"],["du","gingst","kamst","fuhrst"],["er / sie / es","**ging**","**kam**","**fuhr**"],["wir","gingen","kamen","fuhren"],["ihr","gingt","kamt","fuhrt"],["sie / Sie","gingen","kamen","fuhren"]]},"examples":[{"de":"Am Montag **fuhr** ich mit dem Velo ins Büro.","en":"W poniedziałek pojechałem do biura rowerem."},{"de":"Die Gäste **kamen** um 19 Uhr.","en":"Goście przyszli o 19.00."}],"source":"flexion"},{"title":"Częste czasowniki nieregularne: ucz się trzech form","text":"Nowego tematu nie da się przewidzieć, więc ucz się każdego czasownika nieregularnego jako zestawu: bezokolicznik, Präteritum, Perfekt.","table":{"caption":"Czasowniki nieregularne, których często potrzebujesz","head":["bezokolicznik","Präteritum","Perfekt"],"rows":[["bleiben","**blieb**","ist geblieben"],["essen","**ass**","hat gegessen"],["finden","**fand**","hat gefunden"],["geben","**gab**","hat gegeben"],["lesen","**las**","hat gelesen"],["nehmen","**nahm**","hat genommen"],["schlafen","**schlief**","hat geschlafen"],["schreiben","**schrieb**","hat geschrieben"],["sprechen","**sprach**","hat gesprochen"],["treffen","**traf**","hat getroffen"]]},"examples":[{"de":"Ich **traf** meine Kollegin am Bahnhof.","en":"Spotkałem koleżankę z pracy na dworcu."},{"de":"Nach dem Essen **schrieb** sie noch zwei E-Mails.","en":"Po jedzeniu napisała jeszcze dwa e-maile."}],"source":"stammformen"},{"title":"Czasowniki mieszane: -te i nowy temat","text":"Kilka czasowników dodaje *-te* jak czasowniki regularne, ale też zmienia temat jak nieregularne: *denken → **dachte***, *bringen → **brachte***, *kennen → **kannte***, *nennen → **nannte***, *rennen → **rannte*** i *wissen → **wusste***. Imiesłów (Partizip II) zmienia się tak samo: *gedacht, gebracht, gekannt, gewusst*.","examples":[{"de":"Ich **dachte** lange über das Angebot **nach**.","en":"Długo zastanawiałem się nad tą ofertą.","note":"*nachdenken* jest mieszany i rozdzielnie złożony: *dachte … nach*."},{"de":"Wir **kannten** niemanden in Zürich.","en":"Nie znaliśmy nikogo w Zurychu."},{"de":"Sie **wusste** die Antwort sofort.","en":"Od razu znała odpowiedź."}],"source":"schwach"},{"title":"Czasowniki modalne: -te i bez umlautu","text":"Czasowniki modalne dodają *-te* i **tracą umlaut**: *können → konnte*, *müssen → musste*, *dürfen → durfte*. *mögen* zmienia też *g* na *ch*: *mochte*. Z umlautem (*könnte, müsste, dürfte*) to tryb przypuszczający (Konjunktiv II), który znaczy coś innego.","table":{"caption":"Präteritum czasowników modalnych","head":["","können","müssen","dürfen","wollen","sollen","mögen"],"rows":[["ich / er / sie / es","**konnte**","**musste**","**durfte**","**wollte**","**sollte**","**mochte**"],["du","konntest","musstest","durftest","wolltest","solltest","mochtest"],["wir / sie / Sie","konnten","mussten","durften","wollten","sollten","mochten"],["ihr","konntet","musstet","durftet","wolltet","solltet","mochtet"]]},"examples":[{"de":"Ich **konnte** gestern nicht zum Kurs kommen.","en":"Wczoraj nie mogłem przyjść na kurs."},{"de":"Wir **mussten** lange auf den Bus warten.","en":"Musieliśmy długo czekać na autobus."},{"de":"Als Kind **mochte** ich keinen Spinat.","en":"Jako dziecko nie lubiłem szpinaku."}],"source":"stammformen"},{"title":"sein, haben, werden","text":"Tych trzech naucz się na pamięć. *haben* jest prawie regularny, ale zwróć uwagę na podwójne *t*: *hatte*. *werden* ma *-e* nawet dla *ich* i *er*: *wurde*.","table":{"caption":"Präteritum czasowników sein, haben i werden","head":["","sein","haben","werden"],"rows":[["ich","**war**","**hatte**","**wurde**"],["du","warst","hattest","wurdest"],["er / sie / es","**war**","**hatte**","**wurde**"],["wir","waren","hatten","wurden"],["ihr","wart","hattet","wurdet"],["sie / Sie","waren","hatten","wurden"]]},"examples":[{"de":"Gestern **war** ich in Bern.","en":"Wczoraj byłem w Bernie."},{"de":"Der Zug **hatte** zwanzig Minuten Verspätung.","en":"Pociąg miał dwadzieścia minut opóźnienia."},{"de":"Es **wurde** kalt, und wir gingen nach Hause.","en":"Zrobiło się zimno i poszliśmy do domu."}],"source":"stammformen"},{"title":"Czasowniki rozdzielnie złożone: przedrostek idzie na koniec","text":"Czasowniki rozdzielnie złożone rozdzielają się w Präteritum tak samo jak w czasie teraźniejszym: czasownik stoi na drugim miejscu, przedrostek na końcu. W zdaniu podrzędnym (z *weil, dass, als* …) czasownik idzie na koniec i znów pisze się go jako jedno słowo.","examples":[{"de":"Der Zug **kam** um 8 Uhr **an**.","en":"Pociąg przyjechał o 8.00.","note":"*ankommen → kam … an*"},{"de":"Gestern **rief** mich meine Kollegin **an**.","en":"Wczoraj zadzwoniła do mnie koleżanka z pracy."},{"de":"Wir waren nervös, weil der Zug so spät **ankam**.","en":"Denerwowaliśmy się, bo pociąg przyjechał tak późno.","note":"Zdanie podrzędne: jedno słowo na końcu."}],"source":"praeverb"},{"title":"Kiedy go używać: pisanie a mówienie","text":["**Pisanie:** opowiadania, relacje, artykuły prasowe i teksty o przeszłości używają przeważnie Präteritum.","**Mówienie:** w rozmowie większość ludzi używa czasu Perfekt: *Was **hast** du am Wochenende **gemacht**?*","Im bardziej oficjalna sytuacja, tym częściej słychać Präteritum."],"examples":[{"de":"Am Montag **fuhr** Herr Keller wie immer mit der S-Bahn nach Zürich.","en":"W poniedziałek pan Keller jak zawsze pojechał kolejką S-Bahn do Zurychu.","note":"Opowiadanie pisane: Präteritum."},{"de":"Was **hast** du am Samstag **gemacht**? – Ich **bin** wandern **gegangen**.","en":"Co robiłeś w sobotę? – Byłem na wędrówce.","note":"Rozmowa: Perfekt."},{"de":"Ich **war** gestern krank und **konnte** nicht arbeiten.","en":"Wczoraj byłem chory i nie mogłem pracować.","note":"*war* i czasowniki modalne są częste także w rozmowie."}],"source":"schrift"}],"exceptions":[{"title":"Szwajcarski niemiecki: w dialekcie nie ma Präteritum","text":["Szwajcarski niemiecki, tak jak inne dialekty południowe (górnoniemieckie), praktycznie nie ma Präteritum: do każdego zdarzenia w przeszłości używa czasu Perfekt. Dlatego Szwajcarzy rzadko mówią *ging* czy *kam*, nawet gdy mówią standardowym niemieckim.","Za to w **pisanym** standardowym niemieckim Präteritum jest wszędzie: w gazecie, w pracy, w książkach. Musisz go płynnie czytać i używać we własnych tekstach."],"examples":[{"de":"Ich **bin** gestern in Bern **gewesen**.","en":"Byłem wczoraj w Bernie.","note":"Tak zwykle mówi Szwajcar."},{"de":"Ich **war** gestern in Bern.","en":"Byłem wczoraj w Bernie.","note":"Tak napiszesz to na piśmie."}],"source":"praet"},{"title":"-ete po spółgłosce + n lub m","text":"Czasowniki regularne dostają **-ete** także wtedy, gdy temat kończy się na spółgłoskę plus *n* lub *m*, żeby łatwiej było je wymówić: *öffnen → öffnete*, *rechnen → rechnete*, *regnen → es regnete*, *atmen → atmete*. **Ale** po *r*, *l* lub *h* + *n* nie ma dodatkowego *e*: *lernen → lernte*, *wohnen → wohnte*.","examples":[{"de":"Es **regnete** den ganzen Tag, deshalb blieben wir zu Hause.","en":"Cały dzień padało, więc zostaliśmy w domu."},{"de":"Die Chefin **öffnete** das Fenster.","en":"Szefowa otworzyła okno."}],"source":"schwach"},{"title":"Perfekt na piśmie, gdy coś wciąż ma znaczenie teraz","text":"Nawet w tekście pisanym przejdź na Perfekt, gdy chcesz podkreślić, że coś z przeszłości wciąż ma skutki teraz.","examples":[{"de":"Die SBB **hat** den Fahrplan **geändert**: Ab Montag fährt der Zug um 7.32 Uhr.","en":"Koleje SBB zmieniły rozkład jazdy: od poniedziałku pociąg odjeżdża o 7.32."}],"source":"gebrauch"}],"mistakes":[{"wrong":"Er gehte nach Hause.","right":"Er **ging** nach Hause.","why":"*gehen* jest nieregularny: nowy temat, bez *-te*. Kto zna angielskie *-ed*, często dodaje *-te* do każdego czasownika, ale czasowników nieregularnych trzeba się nauczyć."},{"wrong":"Sie gingt ins Büro.","right":"Sie **ging** ins Büro.","why":"*er / sie / es* nie ma w Präteritum końcówki. *-t* należy do czasu teraźniejszego (*sie geht*)."},{"wrong":"Ich denkte an dich.","right":"Ich **dachte** an dich.","why":"*denken* to czasownik mieszany: *-te* i nowy temat, *dachte*."},{"wrong":"Gestern arbeitet sie bis 20 Uhr.","right":"Gestern **arbeitete** sie bis 20 Uhr.","why":"Po *-t* lub *-d* w czasie przeszłym dodaje się *-ete*. *arbeitet* to czas teraźniejszy."},{"wrong":"Ich könnte gestern nicht kommen.","right":"Ich **konnte** gestern nicht kommen.","why":"Czasowniki modalne tracą w Präteritum umlaut. *könnte* to tryb przypuszczający (Konjunktiv II): mógłby, byłby w stanie."},{"wrong":"Ich möchte dich gestern anrufen.","right":"Ich **wollte** dich gestern anrufen.","why":"*möchte* nie ma własnej formy przeszłej. W przeszłości użyj *wollte*."},{"wrong":"Der Zug ankam um 8 Uhr.","right":"Der Zug **kam** um 8 Uhr **an**.","why":"Czasowniki rozdzielnie złożone rozdzielają się także w Präteritum: przedrostek idzie na koniec."},{"wrong":"Sahst du gestern das Spiel? (im Chat mit einem Freund)","right":"**Hast** du gestern das Spiel **gesehen**?","why":"W angielskim (*Did you see …?*) i hiszpańskim (*¿Viste …?*) prosty czas przeszły jest w rozmowie normalny. W niemieckiej rozmowie bardziej naturalny jest Perfekt; Präteritum brzmi książkowo."}],"examples":[{"de":"Die Sitzung **begann** um 9 Uhr und **dauerte** zwei Stunden.","en":"Zebranie zaczęło się o 9.00 i trwało dwie godziny."},{"de":"Früher **wohnten** wir in Bern, dann **zogen** wir nach Zürich.","en":"Kiedyś mieszkaliśmy w Bernie, potem przeprowadziliśmy się do Zurychu."},{"de":"Ich **wusste** nicht, dass der Laden am Sonntag geschlossen war.","en":"Nie wiedziałem, że w niedzielę sklep jest zamknięty."},{"de":"Der Chef **brachte** am Freitag Gipfeli für alle **mit**.","en":"W piątek szef przyniósł wszystkim rogaliki.","note":"*mitbringen* jest mieszany i rozdzielnie złożony: *brachte … mit*."},{"de":"Als Kind **wollte** ich Lokführerin werden.","en":"Jako dziecko chciałam zostać maszynistką."},{"de":"Wir **stiegen** in Olten **um** und **kamen** pünktlich in Bern **an**.","en":"Przesiedliśmy się w Olten i punktualnie dojechaliśmy do Berna."},{"de":"Es **regnete**, aber wir **hatten** keinen Schirm.","en":"Padało, a nie mieliśmy parasola."},{"de":"Sie **nahm** das Tram und **war** in zehn Minuten im Büro.","en":"Pojechała tramwajem i po dziesięciu minutach była w biurze."}],"later":"Präteritum w stronie biernej (*Die Brücke **wurde** 1950 **gebaut**.*) pojawi się w temacie o stronie biernej. Starych form, które spotkasz tylko w książkach (*du kamest*), nie musisz się uczyć.","selfcheck":{"types":{"form":{"label":"Forma Präteritum","instruction":"Wpisz czasownik z nawiasu w Präteritum, we właściwej osobie. Napisz jedno słowo.","example":{"q":"Wir ___ am Montag bis 20 Uhr. (arbeiten)","a":"arbeiteten","why":"Czasownik regularny, temat kończy się na *-t*: *arbeit-ete-*, plus *-n* dla *wir*."}},"rewrite":{"label":"Teraźniejszy → przeszły","instruction":"Przepisz zdanie w Präteritum. Zachowaj ten sam szyk wyrazów. Napisz całe zdanie.","example":{"q":"Das Meeting fängt um 9 Uhr an.","a":"Das Meeting fing um 9 Uhr an.","why":"*anfangen* jest nieregularny i rozdzielnie złożony: *fing … an*."}},"pick":{"label":"W mowie czy na piśmie?","instruction":"Przeczytaj opis sytuacji (prostym niemieckim) i obie wersje. Obie są poprawne po niemiecku. Napisz **a** lub **b**, czyli wersję, która w tej sytuacji brzmi bardziej naturalnie.","example":{"q":"Du erzählst deiner Mitbewohnerin, was heute Morgen passiert ist. a) Ich habe meinen Schlüssel verloren. b) Ich verlor meinen Schlüssel.","a":"a","why":"Rozmowa: Perfekt. Präteritum *verlor* brzmi jak pisane opowiadanie."}}},"items":[{"type":"form","q":"Gestern ___ ich bis 19 Uhr im Büro. (bleiben)","a":["blieb"],"why":"Nieregularny: *bleiben – blieb – geblieben*, bez końcówki dla *ich*."},{"type":"form","q":"Die Chefin ___ uns am Morgen eine Mail. (schicken)","a":["schickte"],"why":"Regularny: *schick-* + *-te*, bez dodatkowej końcówki dla *sie*."},{"type":"form","q":"Anna ___ den Bericht kurz vor Mitternacht. (beenden)","a":["beendete"],"why":"Regularny, temat kończy się na *-d*: *-ete*."},{"type":"form","q":"Er ___ die ganze Nacht an die Prüfung. (denken)","a":["dachte"],"why":"Czasownik mieszany: *denken – dachte – gedacht*."},{"type":"form","q":"Wir ___ leider nicht zur Sitzung kommen. (können)","a":["konnten"],"why":"Czasownik modalny: w Präteritum bez umlautu. *könnten* byłoby trybem przypuszczającym (Konjunktiv II)."},{"type":"form","q":"Ich ___ nicht, dass das Büro am Montag geschlossen war. (wissen)","a":["wusste"],"why":"*wissen – wusste – gewusst*, bez końcówki dla *ich*."},{"type":"form","q":"Ihr ___ gestern sehr spät zu Hause. (sein)","a":["wart"],"why":"*sein* w Präteritum: *ihr wart*."},{"type":"rewrite","q":"Der Bus fährt um 7 Uhr ab.","a":["Der Bus fuhr um 7 Uhr ab."],"why":"*abfahren* jest nieregularny i rozdzielnie złożony: *fuhr … ab*."},{"type":"rewrite","q":"Ich rufe meine Mutter am Abend an.","a":["Ich rief meine Mutter am Abend an."],"why":"*anrufen – rief an – angerufen*, przedrostek na końcu."},{"type":"pick","q":"Du erzählst einer Kollegin an der Kaffeemaschine von deinem Wochenende. a) Am Samstag bin ich nach Luzern gefahren. b) Am Samstag fuhr ich nach Luzern.","a":["a"],"why":"Rozmowa: Perfekt. *fuhr* pasuje do tekstu pisanego."},{"type":"pick","q":"Du schreibst eine kurze Geschichte für die Kurszeitung. a) Es hat geregnet, und Lea hat am Bahnhof Bern auf ihren Bruder gewartet. b) Es regnete, und Lea wartete am Bahnhof Bern auf ihren Bruder.","a":["b"],"why":"Pisane opowiadanie: Präteritum."},{"type":"pick","q":"Du schreibst einem Freund eine Chatnachricht. a) Sahst du gestern das Spiel? b) Hast du gestern das Spiel gesehen?","a":["b"],"why":"Czat jest jak rozmowa: Perfekt. *Sahst du …?* brzmi książkowo."}]},"sources":[{"id":"praet","title":"grammis: Präteritum (prosty czas przeszły; w dialektach południowych zastępuje go Perfekt)","url":"https://grammis.ids-mannheim.de/terminologie/211"},{"id":"flexion","title":"grammis: Verbflexion nach Tempus und Modus (formy czasownika według czasu i trybu)","url":"https://grammis.ids-mannheim.de/progr@mm/4047"},{"id":"schwach","title":"grammis: Schwache Verben (czasowniki regularne, -te / -ete, czasowniki mieszane)","url":"https://grammis.ids-mannheim.de/progr@mm/4073"},{"id":"stammformen","title":"grammis: Verbale Stammformen (tematy czasowników: mocnych, mieszanych, modalnych i posiłkowych)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/2769"},{"id":"praeverb","title":"grammis: Präverbfügung (czasowniki rozdzielnie złożone)","url":"https://grammis.ids-mannheim.de/terminologie/1185"},{"id":"schrift","title":"grammis: Präteritum versus Präsensperfekt (użycie w mowie i na piśmie)","url":"https://grammis.ids-mannheim.de/kontrastive-grammatik/4206"},{"id":"gebrauch","title":"grammis: Die Vorstellung hat bereits begonnen oder begann bereits? Präteritum czy Perfekt","url":"https://grammis.ids-mannheim.de/fragen/3287"}]},{"id":"als-wenn","number":2,"added":"2026-11-07","level":"B1.1","title":"als / wenn","title_en":"Jak powiedzieć „kiedy”: als, wenn i wann","summary":"Używaj *als* dla jednego razu w przeszłości, *wenn* dla „za każdym razem” oraz dla teraźniejszości i przyszłości, a *wann* w pytaniach.","purpose":["Angielski ma jedno słowo: *when*. Niemiecki ma trzy: **als**, **wenn** i **wann**. Włoskie *quando*, francuskie *quand* i hiszpańskie *cuando* też mają jedno słowo na wszystkie trzy, więc ten wybór jest nowy prawie dla każdego.","Potrzebujesz tego zawsze, gdy opowiadasz historię ze swojego życia (*Als ich in die Schweiz kam, …*), mówisz o przyzwyczajeniach (*Wenn ich Frühschicht habe, …*) albo pytasz o czas (*Wann beginnt der Kurs?*)."],"logic":["Zadaj sobie dwa pytania. **Czy to pytanie o czas?** Wtedy *wann*. **Czy to jeden raz w przeszłości?** Wtedy *als*. Wszystko inne to *wenn*.","**als** = **jedno** zdarzenie lub **jeden okres** w przeszłości: *Als ich ankam, …* (jedna chwila), *Als ich ein Kind war, …* (dzieciństwo zdarzyło się raz, nawet jeśli trwało lata).","**wenn** = **za każdym razem**, w przeszłości, teraźniejszości lub przyszłości, a także **jeśli**: *(Immer) wenn ich nach Bern fahre, …*, *Wenn es morgen regnet, …*","**wann** = **kiedy? o której?**, w pytaniach bezpośrednich i zależnych: *Wann kommst du?* *Ich weiss nicht, wann er kommt.*","*als* i *wenn* rozpoczynają zdanie podrzędne, więc odmieniony czasownik idzie na **koniec**. Jeśli to zdanie stoi na początku, zdanie główne **zaczyna się od czasownika**: *Als ich ankam, **regnete** es.*"],"rules":[{"title":"Przegląd: als, wenn czy wann?","text":"Decydują dwie rzeczy: czy to **jeden raz**, czy **za każdym razem**, i czy to **przeszłość**, czy **teraźniejszość / przyszłość**? Pytania o czas zawsze mają *wann*.","table":{"caption":"Które słowo na „kiedy”?","head":["","przeszłość","teraźniejszość / przyszłość"],"rows":[["jeden raz","**als**","**wenn**"],["za każdym razem (wielokrotnie)","**wenn**","**wenn**"],["pytanie: kiedy? o której?","**wann**","**wann**"]]},"examples":[{"de":"**Als** ich gestern ins Büro kam, war der Kaffee schon fertig.","en":"Kiedy wczoraj przyszedłem do biura, kawa była już gotowa.","note":"Jeden raz w przeszłości → *als*."},{"de":"**Wenn** ich ins Büro komme, trinke ich zuerst einen Kaffee.","en":"Kiedy przychodzę do biura, najpierw piję kawę.","note":"Za każdym razem, teraźniejszość → *wenn*."},{"de":"**Wann** kommst du ins Büro?","en":"Kiedy przyjdziesz do biura?","note":"Pytanie → *wann*."}],"source":"temporal"},{"title":"als: jedno zdarzenie lub jeden okres w przeszłości","text":["Używaj **als** dla czegoś, co wydarzyło się **raz** w przeszłości: chwili (*Als das Telefon klingelte, …*) albo okresu, który zdarzył się raz (*Als ich in Genf wohnte, …*, *Als ich ein Kind war, …*).","Zdanie główne może opisywać rzeczy, które w tym okresie działy się często: *Als ich ein Kind war, spielte ich jeden Tag Fussball.* Zdanie z *als* wciąż nazywa jeden okres, więc zostaje *als*."],"examples":[{"de":"**Als** ich 2019 nach Winterthur zog, kannte ich niemanden.","en":"Kiedy w 2019 roku przeprowadziłem się do Winterthuru, nie znałem nikogo."},{"de":"**Als** ich ein Kind war, spielte ich jeden Tag Fussball.","en":"Kiedy byłem dzieckiem, codziennie grałem w piłkę.","note":"*jeden Tag* jest w zdaniu głównym. Dzieciństwo to jeden okres, więc zdanie podrzędne ma *als*."},{"de":"Ich war gerade unter der Dusche, **als** das Telefon klingelte.","en":"Akurat byłem pod prysznicem, kiedy zadzwonił telefon."}],"source":"als"},{"title":"wenn: za każdym razem, także w przeszłości","text":"Dla czegoś, co działo się **wielokrotnie** w przeszłości, użyj **wenn**, nie *als*. Słowa takie jak *immer* (zawsze) czy *jedes Mal* (za każdym razem) jasno to pokazują: *Immer wenn …*, *Jedes Mal, wenn …*","examples":[{"de":"**Immer wenn** ich meine Grossmutter besuchte, backte sie einen Kuchen.","en":"Zawsze, kiedy odwiedzałem babcię, piekła ciasto."},{"de":"**Wenn** wir früher Ferien hatten, fuhren wir ans Meer.","en":"Kiedyś, gdy mieliśmy wakacje, jeździliśmy nad morze."},{"de":"**Jedes Mal, wenn** ich den Zug nahm, hatte er Verspätung.","en":"Za każdym razem, gdy jechałem pociągiem, miał opóźnienie."}],"source":"wenn-temporal"},{"title":"wenn: teraz i w przyszłości oraz = jeśli","text":"W teraźniejszości i przyszłości **wenn** obejmuje zarówno angielskie *when*, jak i *if* (po polsku „kiedy” i „jeśli”). Pasuje do przyzwyczajeń (*Wenn ich im Homeoffice arbeite, …*), do jednego zdarzenia, które dopiero nastąpi (*Wenn das Paket kommt, …*), i do warunków (*Wenn es regnet, …*).","examples":[{"de":"**Wenn** ich im Homeoffice arbeite, mache ich mittags einen Spaziergang.","en":"Kiedy pracuję z domu, w południe idę na spacer."},{"de":"**Wenn** das Paket morgen kommt, rufe ich dich an.","en":"Kiedy jutro przyjdzie paczka, zadzwonię do ciebie.","note":"Angielski wybiera między *when* a *if* (polski między „kiedy” a „jeśli”). Niemiecki używa *wenn* w obu przypadkach."},{"de":"**Wenn** es morgen regnet, bleiben wir zu Hause.","en":"Jeśli jutro będzie padać, zostaniemy w domu."}],"source":"wenn"},{"title":"wann: pytania bezpośrednie i zależne","text":["**wann** pyta o czas. W pytaniu bezpośrednim czasownik stoi na drugim miejscu: *Wann **fährt** der Bus?*","W pytaniu zależnym, po *Weisst du, …*, *Ich weiss nicht, …* albo *Können Sie mir sagen, …*, nadal jest *wann*, a czasownik idzie na **koniec**."],"examples":[{"de":"**Wann** fährt der nächste Bus nach Wil?","en":"Kiedy odjeżdża następny autobus do Wil?"},{"de":"Weisst du, **wann** das Meeting **beginnt**?","en":"Wiesz, kiedy zaczyna się spotkanie?"},{"de":"Ich weiss noch nicht, **wann** ich Ferien **nehme**.","en":"Jeszcze nie wiem, kiedy wezmę urlop."}],"source":"w"},{"title":"Szyk: czasownik na końcu, potem czasownik na początku","text":"W zdaniu z *als* lub *wenn* odmieniony czasownik idzie na **koniec**. To zdanie może stać na początku albo na drugim miejscu. Jeśli stoi na początku, zajmuje pierwsze miejsce, więc zdanie główne **zaczyna się od czasownika**.","table":{"caption":"To samo zdanie w obu kolejnościach","head":["","część 1","część 2"],"rows":[["zdanie podrzędne na początku","**Als** ich nach Hause **kam**,","**war** niemand da."],["zdanie podrzędne na drugim miejscu","Niemand **war** da,","**als** ich nach Hause **kam**."]]},"examples":[{"de":"**Wenn** ich müde **bin**, **trinke** ich einen Kaffee.","en":"Kiedy jestem zmęczony, piję kawę."},{"de":"Ich trinke einen Kaffee, **wenn** ich müde **bin**.","en":"Piję kawę, kiedy jestem zmęczony."},{"de":"**Als** wir in Genf **angekommen sind**, **hat** es geregnet.","en":"Kiedy przyjechaliśmy do Genewy, padało.","note":"Gdy czasownik ma dwie części, odmieniona (*sind*) idzie na sam koniec."}],"source":"integration"}],"exceptions":[{"title":"als znaczy też „niż”","text":["Po stopniu wyższym (*grösser, älter, mehr, lieber*) **als** znaczy *niż*. Nie ma to nic wspólnego z czasem.","Przy formie podstawowej przymiotnika użyj **so … wie** (tak … jak): *so gross wie*. W codziennej mowie, zwłaszcza na południu, słyszy się też *grösser wie*. Na piśmie i na egzaminie używaj *grösser als*."],"examples":[{"de":"Zürich ist **grösser als** Bern.","en":"Zurych jest większy niż Berno."},{"de":"Ich trinke **lieber** Tee **als** Kaffee.","en":"Wolę pić herbatę niż kawę."},{"de":"Das neue Büro ist **so gross wie** das alte.","en":"Nowe biuro jest tak duże jak stare."}],"source":"vergleich"},{"title":"als + rzeczownik znaczy „jako”","text":"*als* + rzeczownik, bez czasownika, nazywa rolę: *als Lehrerin* (jako nauczycielka), *als Kind* (jako dziecko). *Als Kind* to krótszy sposób powiedzenia *Als ich ein Kind war*.","examples":[{"de":"Sie arbeitet **als** Pflegefachfrau im Spital.","en":"Pracuje jako pielęgniarka w szpitalu."},{"de":"**Als** Kind wohnte ich in Lugano.","en":"Jako dziecko mieszkałem w Lugano.","note":"*Als Kind* zajmuje pierwsze miejsce, więc zaraz po nim idzie czasownik (*wohnte*)."}],"source":"als"}],"mistakes":[{"wrong":"Wenn ich gestern nach Hause kam, war niemand da.","right":"**Als** ich gestern nach Hause kam, war niemand da.","why":"Jeden raz w przeszłości → *als*. Angielskie *when*, francuskie *quand*, włoskie *quando* i hiszpańskie *cuando* nie robią tego rozróżnienia, więc uczący się sięgają po *wenn*."},{"wrong":"Immer als ich Kopfweh hatte, nahm ich eine Tablette.","right":"Immer **wenn** ich Kopfweh hatte, nahm ich eine Tablette.","why":"*immer* pokazuje, że działo się to wielokrotnie. Powtarzające się → *wenn*, nawet w przeszłości."},{"wrong":"Wenn kommst du?","right":"**Wann** kommst du?","why":"Pytanie o czas wymaga *wann*. Angielskie *when?*, francuskie *quand ?*, włoskie *quando?* i hiszpańskie *¿cuándo?* to to samo słowo co w zdaniach oznajmujących, więc uczący się je mylą."},{"wrong":"Ich weiss nicht, wenn der Zug fährt.","right":"Ich weiss nicht, **wann** der Zug fährt.","why":"Pytanie zależne o czas to nadal *wann*, tak jak angielskie „I don't know when” jest pytaniem."},{"wrong":"Ich weiss nicht, wenn er heute kommt. (= whether)","right":"Ich weiss nicht, **ob** er heute kommt.","why":"Angielskie *if*, francuskie *si*, włoskie *se* i hiszpańskie *si* znaczą też „czy”. Po niemiecku „czy” to *ob*; *wenn* znaczy „jeśli” tylko w warunku."},{"wrong":"Als ich war ein Kind, …","right":"Als ich ein Kind **war**, …","why":"*als* i *wenn* przesuwają odmieniony czasownik na koniec swojego zdania."},{"wrong":"Als ich ein Kind war, ich wohnte in Lugano.","right":"Als ich ein Kind war, **wohnte ich** in Lugano.","why":"Po zdaniu podrzędnym zdanie główne zaczyna się od czasownika. Angielski i francuski stawiają tu najpierw podmiot, więc to częsty błąd przeniesiony z innego języka."},{"wrong":"Wo ich klein war, …","right":"**Als** ich klein war, …","why":"W szwajcarskim dialekcie często słyszy się w tej roli *wo*. W standardowym niemieckim pisz i mów *als*."}],"examples":[{"de":"**Als** ich in die Schweiz kam, sprach ich kein Wort Deutsch.","en":"Kiedy przyjechałem do Szwajcarii, nie mówiłem ani słowa po niemiecku."},{"de":"**Als** meine Tochter geboren wurde, wohnten wir noch in Basel.","en":"Kiedy urodziła się moja córka, mieszkaliśmy jeszcze w Bazylei."},{"de":"**Wenn** ich Frühschicht habe, stehe ich um fünf Uhr auf.","en":"Kiedy mam poranną zmianę, wstaję o piątej."},{"de":"Früher sind wir jedes Wochenende in die Berge gefahren, **wenn** das Wetter schön war.","en":"Kiedyś co weekend jeździliśmy w góry, kiedy była ładna pogoda."},{"de":"**Wenn** du am Bahnhof bist, schreib mir kurz.","en":"Kiedy będziesz na dworcu, napisz mi krótką wiadomość."},{"de":"**Wann** hast du morgen Feierabend?","en":"O której jutro kończysz pracę?"},{"de":"Können Sie mir sagen, **wann** die Post am Samstag schliesst?","en":"Czy może mi Pani powiedzieć, o której w sobotę zamykają pocztę?"},{"de":"Mein Bruder ist drei Jahre jünger **als** ich.","en":"Mój brat jest o trzy lata młodszy ode mnie."}],"later":"Inne słowa czasowe wprowadzające zdania mają ten sam szyk (czasownik na końcu) i pojawią się w kolejnych lekcjach: *nachdem* (po tym, jak), *bevor* (zanim), *während* (podczas gdy), *seit* (odkąd), *bis* (aż, dopóki nie), *sobald* (gdy tylko). *als ob* (jak gdyby) też pojawi się później.","selfcheck":{"types":{"choose":{"label":"als, wenn czy wann?","instruction":"Wpisz brakujące słowo: *als*, *wenn* lub *wann*. Napisz tylko jedno słowo. Zapytaj siebie: czy to pytanie o czas, jeden raz w przeszłości, czy za każdym razem / teraz / później? W jednym zdaniu luka to porównanie („niż”).","example":{"q":"___ ich gestern nach Hause kam, war niemand da.","a":"Als","why":"*gestern* = jeden raz w przeszłości → *als*."}},"join":{"label":"Połącz zdania","instruction":"Połącz dwa zdania za pomocą *als* lub *wenn*. Słowo wybierz sam. Postaw czasownik zdania z *als*/*wenn* na końcu. Możesz zacząć od *als*/*wenn* (wtedy zdanie główne zaczyna się od czasownika) albo postawić to zdanie na drugim miejscu. Nie zmieniaj czasów. Napisz całe zdanie.","example":{"q":"Ich kam ins Büro. Das Telefon klingelte. (ein Moment, gestern)","a":"Als ich ins Büro kam, klingelte das Telefon.","why":"Jeden raz w przeszłości → *als*. *kam* idzie na koniec, a zdanie główne zaczyna się od czasownika (*klingelte*)."}}},"items":[{"type":"choose","q":"___ ich 18 war, habe ich die Autoprüfung gemacht.","a":["Als"],"why":"Osiemnaście lat miało się raz, w przeszłości → *als*."},{"type":"choose","q":"Jedes Mal, ___ ich in Italien war, habe ich meine Grosseltern besucht.","a":["wenn"],"why":"*Jedes Mal* = wielokrotnie, więc *wenn*, nawet w przeszłości."},{"type":"choose","q":"___ beginnt der Deutschkurs?","a":["Wann"],"why":"Pytanie o czas → *wann*."},{"type":"choose","q":"___ du morgen Zeit hast, können wir zusammen essen.","a":["Wenn"],"why":"Przyszłość, a zarazem warunek (jeśli) → *wenn*."},{"type":"choose","q":"Weisst du, ___ der letzte Zug nach Luzern fährt?","a":["wann"],"why":"Pytanie zależne o czas → *wann*, z czasownikiem (*fährt*) na końcu."},{"type":"choose","q":"___ wir letzten Winter in Davos waren, hat es die ganze Woche geschneit.","a":["Als"],"why":"Jeden pobyt, zeszłej zimy → jeden raz w przeszłości → *als*."},{"type":"choose","q":"Mein Handy klingelt immer, ___ ich in einer Sitzung bin.","a":["wenn"],"why":"*immer*, teraźniejszość → za każdym razem → *wenn*."},{"type":"choose","q":"Meine Schwester ist zwei Jahre älter ___ ich.","a":["als"],"why":"Po stopniu wyższym (*älter*) *als* znaczy „niż”."},{"type":"join","q":"Ich war 20. Ich zog nach Zürich.","a":["Als ich 20 war, zog ich nach Zürich.","Ich zog nach Zürich, als ich 20 war.","Als ich nach Zürich zog, war ich 20.","Ich war 20, als ich nach Zürich zog."],"why":"Dwadzieścia lat miało się raz, w przeszłości → *als*. *war* idzie na koniec; jeśli zdanie podrzędne stoi na początku, zdanie główne zaczyna się od *zog*."},{"type":"join","q":"Es regnet. Ich nehme das Tram.","a":["Wenn es regnet, nehme ich das Tram.","Immer wenn es regnet, nehme ich das Tram.","Wenn es regnet, nehme ich immer das Tram.","Ich nehme das Tram, wenn es regnet.","Ich nehme immer das Tram, wenn es regnet."],"why":"Teraźniejszość, za każdym razem, gdy pada → *wenn*. *regnet* idzie na koniec; po zdaniu podrzędnym zdanie główne zaczyna się od *nehme*."}]},"sources":[{"id":"als","title":"grammis, słownik spójników: als (spójnik czasowy, czasownik na końcu; także als + rzeczownik)","url":"https://grammis.ids-mannheim.de/konnektoren/407056"},{"id":"wenn","title":"grammis, słownik spójników: wenn (czasowy i warunkowy, czasownik na końcu)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"},{"id":"wenn-temporal","title":"grammis: Konditionalsätze (w tym czasowe wenn dla zdarzeń powtarzających się i pojedynczych)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/2101"},{"id":"temporal","title":"grammis: Temporalsätze (zdania czasowe z als, während, nachdem, bevor, seit)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/2104"},{"id":"w","title":"grammis: Termsatzeinleitende W-Elemente (wann, wo, warum … w pytaniach zależnych)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/2093"},{"id":"integration","title":"grammis: Integration der Nebensätze (zdanie podrzędne na pierwszym miejscu)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/1948"},{"id":"vergleich","title":"grammis: Grösser als oder grösser wie? (als i wie w porównaniach)","url":"https://grammis.ids-mannheim.de/fragen/134"}]},{"id":"plusquamperfekt","number":3,"added":"2026-11-07","level":"B1.1","title":"Plusquamperfekt","title_en":"Czas zaprzeszły: co wydarzyło się wcześniej","summary":"Powiedz, co już się wydarzyło przed czymś innym w przeszłości (*Als ich ankam, war der Zug schon abgefahren.*), przede wszystkim po *nachdem*.","purpose":["Plusquamperfekt pokazuje, że coś wydarzyło się **przed** innym zdarzeniem w przeszłości. Cofa cię o krok dalej: *Als ich am Bahnhof ankam, **war** der Zug schon **abgefahren**.* (Kiedy dotarłem na dworzec, pociąg już odjechał.)","Działa jak angielskie *had* + imiesłów czasu przeszłego (*had left*). Spotkasz go głównie w opowiadaniach i relacjach, obok Präteritum, oraz po *nachdem* (po tym, jak)."],"logic":["Forma: weź Perfekt i postaw czasownik posiłkowy w Präteritum: *habe gegessen → **hatte** gegessen*, *bin gefahren → **war** gefahren*.","Ta sama rama czasownikowa co w Perfekt: *hatte / war* na drugim miejscu, Partizip II na końcu. W zdaniu podrzędnym obie części idą na koniec: *…, weil ich den Bus **verpasst hatte**.*","Pomyśl o osi czasu: **Plusquamperfekt** (wcześniej) → **Präteritum / Perfekt** (później) → **teraz**.","Używaj go tylko wtedy, gdy cofasz się w czasie. Jeśli opowiadasz zdarzenia w kolejności, w jakiej się działy, wystarczy Präteritum albo Perfekt.","Typowe słowa sygnałowe: *nachdem* (po tym, jak), *schon* / *bereits* (już), *vorher* / *zuvor* (wcześniej, przedtem), *noch nie* (nigdy wcześniej).","Uważaj na umlaut: *ich **hatte** das gemacht* (zrobiłem to wcześniej) to Plusquamperfekt; *ich **hätte** das gemacht* (zrobiłbym to) to tryb przypuszczający (Konjunktiv II)."],"rules":[{"title":"Forma: hatte / war + Partizip II","text":"Plusquamperfekt to Präteritum czasownika *haben* lub *sein* plus Partizip II czasownika głównego.","table":{"caption":"Plusquamperfekt z hatte i war","head":["","arbeiten (haben)","fahren (sein)"],"rows":[["ich","**hatte** gearbeitet","**war** gefahren"],["du","hattest gearbeitet","warst gefahren"],["er / sie / es","**hatte** gearbeitet","**war** gefahren"],["wir","hatten gearbeitet","waren gefahren"],["ihr","hattet gearbeitet","wart gefahren"],["sie / Sie","hatten gearbeitet","waren gefahren"]]},"examples":[{"de":"Ich **hatte** den Termin **vergessen**.","en":"Zapomniałem o umówionym spotkaniu."},{"de":"Wir **waren** schon nach Hause **gegangen**.","en":"Już wcześniej poszliśmy do domu."}],"source":"plqpf"},{"title":"hatte czy war? Ten sam wybór co w Perfekt","text":["Jeśli czasownik tworzy Perfekt z *sein*, w Plusquamperfekt dostaje **war**. Jeśli z *haben*, dostaje **hatte**.","**war:** ruch z A do B (*fahren, gehen, kommen, einsteigen*), zmiana stanu (*einschlafen, aufwachen, passieren*) oraz *sein, bleiben, werden*.","**hatte:** czasowniki z dopełnieniem w bierniku (*essen, kaufen, schreiben*), większość innych czasowników (*arbeiten, schlafen, warten*) i czasowniki modalne."],"examples":[{"de":"Die Kinder **waren** schon **eingeschlafen**.","en":"Dzieci już zasnęły.","note":"*einschlafen* to zmiana stanu: *ist eingeschlafen*, więc *war*."},{"de":"Er **hatte** schlecht **geschlafen**.","en":"Źle spał.","note":"*schlafen* łączy się z *haben*: *hat geschlafen*, więc *hatte*."},{"de":"Ich **war** noch nie in Genf **gewesen**.","en":"Nigdy wcześniej nie byłem w Genewie."}],"source":"hilfsverb"},{"title":"Znaczenie: o krok dalej w przeszłość","text":"Plusquamperfekt umieszcza zdarzenie **przed** momentem, który sam już jest przeszłością. Używa się go przede wszystkim obok zdarzeń opowiadanych w Präteritum.","examples":[{"de":"Lisa **hatte** ihr Handy zu Hause **vergessen**, deshalb konnte sie nicht anrufen.","en":"Lisa zostawiła telefon w domu, więc nie mogła zadzwonić."},{"de":"Der Film **hatte** schon **angefangen**, als wir ins Kino kamen.","en":"Film już się zaczął, kiedy dotarliśmy do kina."}],"source":"praetperf"},{"title":"nachdem: wcześniejsze zdarzenie","text":["Zdanie z *nachdem* opisuje to, co wydarzyło się **najpierw**. Jego czasownik idzie na koniec. Gdy zdanie z *nachdem* stoi na początku, zdanie główne zaczyna się od czasownika.","Jeśli zdanie główne jest w **przeszłości** (Präteritum albo, w mowie, Perfekt), zdanie z *nachdem* ma **Plusquamperfekt**.","Jeśli zdanie główne jest w **teraźniejszości**, zdanie z *nachdem* ma **Perfekt**."],"table":{"caption":"Czasy z nachdem","head":["","zdanie z nachdem (wcześniej)","zdanie główne (później)"],"rows":[["w przeszłości","Plusquamperfekt: *gegessen hatte*","Präteritum: *ging* (w mowie: *bin gegangen*)"],["w teraźniejszości","Perfekt: *gegessen habe*","Präsens: *gehe*"]]},"examples":[{"de":"Nachdem ich die E-Mail **geschrieben hatte**, ging ich nach Hause.","en":"Po tym, jak napisałem e-mail, poszedłem do domu."},{"de":"Nachdem sie in Olten **umgestiegen war**, las sie die Zeitung.","en":"Po tym, jak przesiadła się w Olten, czytała gazetę."},{"de":"Nachdem wir **angekommen waren**, sind wir ins Hotel gegangen.","en":"Po tym, jak przyjechaliśmy, poszliśmy do hotelu.","note":"W mowie: zdanie główne w Perfekt."},{"de":"Nachdem ich **gegessen habe**, gehe ich spazieren.","en":"Po tym, jak zjem, pójdę na spacer.","note":"Zdanie główne w teraźniejszości: po *nachdem* Perfekt."}],"source":"temporal"},{"title":"bevor: zdanie z bevor to późniejsze zdarzenie","text":"Przy *bevor* (zanim) jest odwrotnie: zdanie z *bevor* dzieje się **później**. Zwykle oba zdania mają ten sam czas przeszły. Możesz użyć Plusquamperfekt w zdaniu głównym, żeby podkreślić, że to się skończyło przed późniejszym zdarzeniem.","examples":[{"de":"Bevor ich ins Büro fuhr, **trank** ich einen Kaffee.","en":"Zanim pojechałem do biura, wypiłem kawę."},{"de":"Bevor sie nach Zürich zog, **hatte** sie drei Jahre in Basel **gewohnt**.","en":"Zanim przeprowadziła się do Zurychu, przez trzy lata mieszkała w Bazylei."}],"source":"temporal"},{"title":"schon, vorher, zuvor: wyraźny krok wstecz","text":"Niemiecki nie ma sztywnego następstwa czasów: czas wybierasz według znaczenia. Gdy *schon*, *vorher* lub *zuvor* wskazuje na czas **przed** jakimś momentem w przeszłości, użyj Plusquamperfekt.","examples":[{"de":"Ich machte mir keine Sorgen, weil ich solche Schmerzen schon vorher **gehabt hatte**.","en":"Nie martwiłem się, bo już wcześniej miewałem takie bóle."},{"de":"Als die Chefin kam, **hatten** wir die Präsentation schon **vorbereitet**.","en":"Kiedy przyszła szefowa, mieliśmy już przygotowaną prezentację."}],"source":"zeitenfolge"}],"exceptions":[{"title":"Mowa w Szwajcarii: ich habe gegessen gehabt","text":["Szwajcarski niemiecki i inne dialekty południowe praktycznie nie mają Präteritum, więc mówiący tworzą wcześniejszą przeszłość z Perfekt: *ich habe gegessen gehabt* zamiast *ich hatte gegessen*. Usłyszysz to w Szwajcarii, nawet w standardowym niemieckim.","Ta podwójna forma nie należy do standardowego systemu czasów i rzadko występuje w tekstach pisanych. Na piśmie używaj **hatte / war** + Partizip II."],"examples":[{"de":"Ich habe schon gegessen gehabt, als du angerufen hast.","en":"Już zjadłem, kiedy zadzwoniłeś.","note":"Tak mówi się w Szwajcarii; na piśmie tego unikaj."},{"de":"Ich **hatte** schon **gegessen**, als du anriefst.","en":"Już zjadłem, kiedy zadzwoniłeś.","note":"Pisany standardowy niemiecki."}],"source":"doppel"},{"title":"hatte gehabt i war gewesen są poprawne","text":"Plusquamperfekt samych czasowników *haben* i *sein* to normalny standardowy niemiecki: *hatte … gehabt*, *war … gewesen*. Nie myl ich ze szwajcarskimi formami podwójnymi.","examples":[{"de":"Ich **hatte** an dem Tag keine Zeit **gehabt**.","en":"Tego dnia nie miałem czasu."},{"de":"Er **war** eine Woche krank **gewesen**.","en":"Był chory przez tydzień."}],"source":"kontrast"},{"title":"Zdarzenia po kolei go nie potrzebują","text":"Gdy opowiadasz zdarzenia w kolejności, w jakiej się działy, każde po prostu następuje po poprzednim. Wystarczy Präteritum (albo Perfekt).","examples":[{"de":"Ich **stand** um 6 Uhr **auf**, **duschte** und **fuhr** ins Büro.","en":"Wstałem o 6.00, wziąłem prysznic i pojechałem do biura."}],"source":"zeitenfolge"}],"mistakes":[{"wrong":"Nachdem ich gegessen habe, ging ich ins Bett.","right":"Nachdem ich gegessen **hatte**, ging ich ins Bett.","why":"Zdanie główne jest w przeszłości (*ging*), więc wcześniejsze zdarzenie z *nachdem* ma Plusquamperfekt. *gegessen habe* pasuje tylko do zdania głównego w teraźniejszości (*…, gehe ich ins Bett*)."},{"wrong":"Gestern hatte ich im Homeoffice gearbeitet. (du erzählst nur, was du gemacht hast)","right":"Gestern **habe** ich im Homeoffice **gearbeitet**.","why":"Plusquamperfekt potrzebuje późniejszego zdarzenia w przeszłości, z którego patrzy się wstecz. Włoski, francuski i hiszpański używają czasu zaprzeszłego swobodniej, na przykład *te l'avevo detto / je te l'avais dit / te lo había dicho* (mówiłem ci). Niemiecki używa tu zwykle czasu Perfekt: *Ich habe es dir doch gesagt!*"},{"wrong":"Als ich ankam, hatte der Zug schon abgefahren.","right":"Als ich ankam, **war** der Zug schon **abgefahren**.","why":"*abfahren* to ruch: Perfekt z *sein* (*ist abgefahren*), więc *war*."},{"wrong":"Ich war den Bericht schon geschrieben.","right":"Ich **hatte** den Bericht schon **geschrieben**.","why":"*schreiben* ma dopełnienie w bierniku: Perfekt z *haben*, więc *hatte*."},{"wrong":"Nachdem ich hatte gegessen, ging ich ins Bett.","right":"Nachdem ich **gegessen hatte**, ging ich ins Bett.","why":"*nachdem* przesuwa czasownik na koniec: najpierw Partizip II, potem *hatte*. Angielskie *after I had eaten* prowadzi do złego szyku."},{"wrong":"Nachdem wir gegessen hatten, wir gingen spazieren.","right":"Nachdem wir gegessen hatten, **gingen wir** spazieren.","why":"Po zdaniu z *nachdem* zdanie główne zaczyna się od czasownika. Angielski i francuski stawiają tu najpierw podmiot, dlatego to częsta pułapka."},{"wrong":"Nachdem dem Essen gingen wir spazieren.","right":"**Nach** dem Essen gingen wir spazieren.","why":"*nachdem* łączy dwa zdania; *nach* + celownik idzie z rzeczownikiem. Angielskie *after* pełni obie funkcje."},{"wrong":"Ich habe schon gegessen gehabt, als du anriefst. (in einem E-Mail)","right":"Ich **hatte** schon **gegessen**, als du anriefst.","why":"Podwójny Perfekt należy do mowy szwajcarskiej i południowoniemieckiej. W pisanym standardowym niemieckim używaj *hatte / war* + Partizip II."}],"examples":[{"de":"Als ich am Bahnhof ankam, **war** der Zug schon **abgefahren**.","en":"Kiedy dotarłem na dworzec, pociąg już odjechał."},{"de":"Nachdem wir das Projekt **abgeschlossen hatten**, gingen wir zusammen essen.","en":"Po tym, jak zakończyliśmy projekt, poszliśmy razem coś zjeść."},{"de":"Sie war müde, weil sie die ganze Nacht nicht **geschlafen hatte**.","en":"Była zmęczona, bo całą noc nie spała."},{"de":"Ich **hatte** meinen Pass zu Hause **vergessen** und musste zurückfahren.","en":"Zapomniałem zabrać z domu paszport i musiałem po niego wrócić."},{"de":"Die Sitzung **hatte** schon **begonnen**, als ich ins Zimmer kam.","en":"Zebranie już się zaczęło, kiedy wszedłem do sali."},{"de":"Bis letzten Sommer **war** er noch nie mit dem Glacier Express **gefahren**.","en":"Do zeszłego lata nigdy nie jechał Glacier Expressem."},{"de":"Nachdem es den ganzen Tag **geregnet hatte**, schien am Abend endlich die Sonne.","en":"Po tym, jak cały dzień padało, wieczorem w końcu wyszło słońce."},{"de":"Wir **hatten** einen Tisch **reserviert**, aber das Restaurant war geschlossen.","en":"Zarezerwowaliśmy stolik, ale restauracja była zamknięta."}],"later":"Plusquamperfekt w stronie biernej (*Das Haus **war** renoviert **worden**.*) i z czasownikami modalnymi (*Ich **hatte** nicht kommen **können**.*) pojawi się później, na poziomie B2.","selfcheck":{"types":{"aux":{"label":"hatte czy war?","instruction":"Wpisz w lukę właściwą formę *hatte* lub *war*. Napisz jedno słowo. Sprawdź osobę: *wir hatten*, *wir waren*.","example":{"q":"Ich ___ den Film schon gesehen.","a":"hatte","why":"*sehen* tworzy Perfekt z *haben* (*habe gesehen*), więc *hatte gesehen*."}},"story":{"label":"Opowiedz historię","instruction":"Te zdania pochodzą z jednego krótkiego opowiadania o Sarze. Postaw czasownik z nawiasu we właściwym czasie: **Präteritum** dla głównych zdarzeń, **Plusquamperfekt** dla tego, co wydarzyło się przed nimi, **Perfekt** dla tego, co ludzie mówią w «cudzysłowie». Wpisz tylko to, co idzie w lukę (jedno lub dwa słowa).","example":{"q":"Paul war hungrig, weil er den ganzen Tag nichts ___. (essen)","a":"gegessen hatte","why":"To, że nic nie jadł, nastąpiło przed głodem: Plusquamperfekt. Po *weil* obie części idą na koniec, a *hatte* na sam koniec."}},"join":{"label":"Połącz za pomocą nachdem","instruction":"Połącz dwa zdania za pomocą *nachdem*. Pierwsze zdanie wydarzyło się najpierw: wstaw je do zdania z *nachdem* w Plusquamperfekt. Drugie zostaw w Präteritum i pomiń *dann*. Napisz całe zdanie i zacznij od *Nachdem*.","example":{"q":"Er duschte. Dann frühstückte er.","a":"Nachdem er geduscht hatte, frühstückte er.","why":"*duschen* łączy się z *haben*: na końcu *geduscht hatte*. Zdanie główne zaczyna się od czasownika."}}},"items":[{"type":"aux","q":"Als ich zur Haltestelle kam, ___ der Bus schon abgefahren.","a":["war"],"why":"*abfahren* to ruch: *ist abgefahren*, więc *war abgefahren*."},{"type":"aux","q":"Tom ___ sein Portemonnaie zu Hause vergessen, deshalb konnte er nicht bezahlen.","a":["hatte"],"why":"*vergessen* ma dopełnienie w bierniku: *hat vergessen*, więc *hatte vergessen*."},{"type":"aux","q":"Wir ___ gerade ins Tram eingestiegen, als es zu regnen begann.","a":["waren"],"why":"*einsteigen* to ruch: *sind eingestiegen*, więc *wir waren*."},{"type":"aux","q":"Er war müde, weil er schlecht geschlafen ___.","a":["hatte"],"why":"*schlafen* łączy się z *haben* (*hat geschlafen*). Tylko *einschlafen* łączy się z *sein*."},{"type":"aux","q":"Sie ___ schon zweimal in Bern gewesen, bevor sie dort eine Stelle fand.","a":["war"],"why":"*sein* tworzy Perfekt z *sein*: *ist gewesen*, więc *war gewesen*."},{"type":"story","q":"Am Freitag ___ Sara erst um 22 Uhr nach Hause. (kommen)","a":["kam"],"why":"Główne zdarzenie opowiadania: Präteritum, *kommen – kam*."},{"type":"story","q":"Sie war sehr müde, weil sie vorher zwölf Stunden ___. (arbeiten)","a":["gearbeitet hatte"],"why":"Praca nastąpiła przed zmęczeniem: Plusquamperfekt, po *weil* obie części na końcu."},{"type":"story","q":"Vor der Haustür merkte sie, dass sie ihren Schlüssel im Büro ___. (vergessen)","a":["vergessen hatte"],"why":"Zapomniała klucza, zanim to zauważyła: Plusquamperfekt."},{"type":"story","q":"Sie ___ ihre Mitbewohnerin an. (anrufen)","a":["rief"],"why":"Kolejne główne zdarzenie: Präteritum. *anrufen* się rozdziela: *rief … an*."},{"type":"story","q":"Sara sagte: «Ich stehe draussen, weil ich meinen Schlüssel ___.» (vergessen)","a":["vergessen habe"],"why":"Sara mówi o tym, co jest teraz, więc Perfekt, jak w rozmowie."},{"type":"story","q":"Nachdem die Mitbewohnerin die Tür ___, ging Sara sofort ins Bett. (öffnen)","a":["geöffnet hatte"],"why":"*nachdem* + zdanie główne w przeszłości: Plusquamperfekt. *öffnen* łączy się z *haben*."},{"type":"join","q":"Wir assen zu Mittag. Dann gingen wir spazieren.","a":["Nachdem wir zu Mittag gegessen hatten, gingen wir spazieren."],"why":"*essen* łączy się z *haben*: *gegessen hatten* dla *wir*. Potem zdanie główne zaczyna się od czasownika: *gingen wir*."},{"type":"join","q":"Sie stieg in Olten aus. Dann wartete sie auf den Bus.","a":["Nachdem sie in Olten ausgestiegen war, wartete sie auf den Bus."],"why":"*aussteigen* to ruch: *ausgestiegen war*. Potem *wartete sie*."}]},"sources":[{"id":"plqpf","title":"grammis: Plusquamperfekt (forma: Präteritum od haben lub sein + Partizip II)","url":"https://grammis.ids-mannheim.de/vggf/2228?termini=term"},{"id":"praetperf","title":"grammis: Präteritumperfekt (Plusquamperfekt: przed momentem w przeszłości)","url":"https://grammis.ids-mannheim.de/terminologie/192"},{"id":"hilfsverb","title":"grammis: Ich bin geschwommen oder ich habe geschwommen? Perfekt z sein czy z haben","url":"https://grammis.ids-mannheim.de/fragen/86"},{"id":"perfektformen","title":"grammis: Perfektformen (Perfekt i Plusquamperfekt mają ten sam wybór: haben czy sein)","url":"https://grammis.ids-mannheim.de/vggf/2226?termini=term"},{"id":"temporal","title":"grammis: Temporalsätze (nachdem, bevor, als)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/2104"},{"id":"zeitenfolge","title":"grammis: Gibt es im Deutschen eine normierte Zeitenfolge? (wybór czasu według znaczenia)","url":"https://grammis.ids-mannheim.de/fragen/165"},{"id":"kontrast","title":"grammis: Das Präteritumperfekt (przykłady, m.in. war gewesen)","url":"https://grammis.ids-mannheim.de/kontrastive-grammatik/4181"},{"id":"doppel","title":"grammis: Warum haben wir das Plusquamperfekt, wenn es nie benutzt wird? (m.in. formy podwójne)","url":"https://grammis.ids-mannheim.de/fragen/6706"},{"id":"sued","title":"grammis: Präteritum versus Präsensperfekt (południowe formy podwójne: ich habe gegessen gehabt)","url":"https://grammis.ids-mannheim.de/kontrastive-grammatik/4206"}]},{"id":"relativsatz","number":4,"added":"2026-11-07","level":"B1.1","title":"Relativpronomen und Relativsatz","title_en":"Zdania względne: kolega, który …, miasto, w którym …","summary":"Opisz osobę lub rzecz dokładniej za pomocą zdania względnego (*die Kollegin, **mit der** ich arbeite*) i używaj *wo* i *was* we właściwych miejscach.","purpose":["Zdanie względne dodaje informację o rzeczowniku **bez zaczynania nowego zdania**: *Das ist die Kollegin. Ich arbeite mit ihr.* zmienia się w *Das ist die Kollegin, **mit der** ich arbeite.* (To jest koleżanka, z którą pracuję.)","Używasz go, żeby powiedzieć, **o którą** osobę lub rzecz ci chodzi, albo żeby dodać szczegół. Przyda ci się w opisach, e-mailach, ogłoszeniach o pracę (*Wir suchen eine Person, **die** gern im Team arbeitet.*) i na egzaminie B1."],"logic":["Zdanie względne zwykle stoi **tuż po rzeczowniku**, który opisuje. Zaczyna się od **zaimka względnego**: *der, die, das* i ich form w poszczególnych przypadkach.","Zadaj sobie dwa pytania. **Który rzeczownik?** Od niego zależą rodzaj i liczba (rodzaj męski, żeński, nijaki, liczba mnoga). **Jaką funkcję pełni zaimek w zdaniu względnym?** Od tego zależy przypadek (mianownik, biernik, celownik, dopełniacz).","Formy są takie same jak formy rodzajnika określonego, z trzema wyjątkami: **denen** (celownik liczby mnogiej) oraz **dessen / deren** (dopełniacz, *którego / której*).","Zdanie względne jest zdaniem podrzędnym: odmieniony czasownik idzie na **koniec**, a **przecinki** pokazują, gdzie zdanie się zaczyna i gdzie kończy.","Niemiecki **nigdy** nie pomija zaimka względnego. Angielski może powiedzieć *the man I met*; niemiecki musi powiedzieć *der Mann, **den** ich getroffen habe*."],"rules":[{"title":"Formy zaimka względnego","text":"Zacznij od rodzajnika określonego. Inne są tylko celownik liczby mnogiej i dopełniacz: **denen**, **dessen**, **deren**. W tabeli są one zaznaczone pogrubieniem.","table":{"caption":"Zaimki względne","head":["","męski","nijaki","żeński","liczba mnoga"],"rows":[["mianownik","der","das","die","die"],["biernik","den","das","die","die"],["celownik","dem","dem","der","**denen**"],["dopełniacz","**dessen**","**dessen**","**deren**","**deren**"]]},"examples":[{"de":"Das ist das Büro, **das** wir gemietet haben.","en":"To jest biuro, które wynajęliśmy."},{"de":"Die Kunden, **denen** wir das Angebot geschickt haben, haben schon geantwortet.","en":"Klienci, którym wysłaliśmy ofertę, już odpowiedzieli."}],"source":"formen"},{"title":"Rodzaj i liczba od rzeczownika, przypadek ze zdania względnego","text":["**Rzeczownik** przed przecinkiem decyduje o **der, die, das** lub liczbie mnogiej. **Czasownik lub przyimek w zdaniu względnym** decyduje o przypadku.","Przypadek rzeczownika w zdaniu głównym nie ma więc znaczenia. Patrz tylko na zdanie względne: czy zaimek jest podmiotem (mianownik), dopełnieniem czasownika takiego jak *sehen, anrufen* (biernik), czy dopełnieniem czasownika takiego jak *helfen, danken, geben jemandem* (celownik)?"],"examples":[{"de":"Das ist der Kollege, **der** neben mir sitzt.","en":"To jest kolega, który siedzi obok mnie.","note":"Mianownik: *der Kollege sitzt neben mir*."},{"de":"Das ist der Kollege, **den** ich gestern angerufen habe.","en":"To jest kolega, do którego wczoraj zadzwoniłem.","note":"Biernik: *ich habe den Kollegen angerufen*."},{"de":"Das ist der Kollege, **dem** ich beim Umzug geholfen habe.","en":"To jest kolega, któremu pomogłem przy przeprowadzce.","note":"Celownik: *ich habe dem Kollegen geholfen*."},{"de":"Ich kenne den Mann, **der** in der Kantine arbeitet.","en":"Znam mężczyznę, który pracuje w stołówce.","note":"*den Mann* to biernik w zdaniu głównym, ale w zdaniu względnym mężczyzna jest podmiotem: **der**."}],"source":"attribut"},{"title":"Czasownik idzie na koniec","text":"Zdanie względne działa jak zdanie z *weil* lub *dass*: odmieniony czasownik stoi **na końcu**. Przy czasowniku modalnym lub w czasie Perfekt odmieniony czasownik stoi po bezokoliczniku lub po Partizip II.","examples":[{"de":"Ich suche eine Stelle, die mir Spass **macht**.","en":"Szukam pracy, która sprawia mi przyjemność."},{"de":"Die Wohnung, die wir gestern besichtigt **haben**, ist leider zu teuer.","en":"Mieszkanie, które wczoraj oglądaliśmy, jest niestety za drogie."},{"de":"Das ist ein Kurs, den man auch online besuchen **kann**.","en":"To jest kurs, na który można chodzić także online."}],"source":"rel"},{"title":"Przecinki wokół zdania względnego","text":"Postaw przecinek **przed** zdaniem względnym. Jeśli zdanie główne ciągnie się dalej, postaw przecinek także **po** nim. Jeśli zdanie względne zaczyna się od przyimka, przecinek stoi przed przyimkiem: *die Firma**,** bei der ich arbeite*.","examples":[{"de":"Der Zug**,** den ich jeden Morgen nehme**,** hatte heute Verspätung.","en":"Pociąg, którym jeżdżę każdego ranka, miał dziś opóźnienie."},{"de":"Die Leute**,** mit denen ich wandern gehe**,** kommen aus dem Aargau.","en":"Ludzie, z którymi chodzę na wędrówki, pochodzą z Argowii."}],"source":"komma"},{"title":"Przyimek + zaimek względny","text":"Jeśli czasownik wymaga przyimka (*arbeiten bei, sprechen über, sich freuen auf*), przyimek stoi **na początku**, przed zaimkiem. Wtedy to **przyimek** decyduje o przypadku: *mit* + celownik, *für* + biernik itd.","examples":[{"de":"Das ist die Kollegin, **mit der** ich das Projekt mache.","en":"To jest koleżanka, z którą robię projekt.","note":"*mit* + celownik, rodzaj żeński: *der*."},{"de":"Die Firma, **bei der** ich arbeite, hat 50 Mitarbeitende.","en":"Firma, w której pracuję, ma 50 pracowników."},{"de":"Der Kurs, **für den** ich mich angemeldet habe, beginnt im Januar.","en":"Kurs, na który się zapisałem, zaczyna się w styczniu.","note":"*für* + biernik, rodzaj męski: *den*."},{"de":"Das sind die Nachbarn, **von denen** ich dir erzählt habe.","en":"To są sąsiedzi, o których ci opowiadałem.","note":"*von* + celownik liczby mnogiej: *denen*."}],"source":"rel"},{"title":"dessen i deren: którego, której","text":["**dessen** odnosi się do rzeczownika rodzaju męskiego lub nijakiego, **deren** do rzeczownika rodzaju żeńskiego lub w liczbie mnogiej. Wybór zależy od **właściciela** (rzeczownika przed przecinkiem), a nie od rzeczy posiadanej.","Rzeczownik po *dessen / deren* **nie ma rodzajnika**: *der Nachbar, dessen Hund …* (nigdy *dessen der Hund*)."],"examples":[{"de":"Ich habe einen Nachbarn, **dessen** Hund jede Nacht bellt.","en":"Mam sąsiada, którego pies szczeka co noc."},{"de":"Das ist die Kollegin, **deren** Mann in Basel arbeitet.","en":"To jest koleżanka, której mąż pracuje w Bazylei."},{"de":"Eltern, **deren** Kinder in die Krippe gehen, müssen früh aufstehen.","en":"Rodzice, których dzieci chodzą do żłobka, muszą wcześnie wstawać."}],"source":"attribut"},{"title":"wo przy miejscach","text":"Po rzeczowniku oznaczającym miejsce możesz użyć **wo** zamiast przyimka + zaimka: *die Stadt, **wo** ich wohne* = *die Stadt, **in der** ich wohne*. Obie formy są poprawne. *wo* jest prostsze i częste w mowie.","examples":[{"de":"Kennst du ein Restaurant, **wo** man gut Fondue essen kann?","en":"Znasz restaurację, gdzie można zjeść dobre fondue?"},{"de":"Das ist das Dorf, **in dem** meine Grosseltern wohnen.","en":"To jest wieś, w której mieszkają moi dziadkowie.","note":"*wo* też jest tu poprawne: *das Dorf, wo …*"}],"source":"wo"},{"title":"was po alles, etwas, nichts, das i po całym zdaniu","text":["Używaj **was** po zaimkach **alles, etwas, nichts** (*das* też jest tu możliwe, ale dużo rzadsze) i po **das** w znaczeniu „to, co”.","Używaj **was** także wtedy, gdy zdanie względne komentuje **całe zdanie główne**, a nie jeden rzeczownik: *…, **was** mich freut* (…, co mnie cieszy)."],"examples":[{"de":"**Alles, was** du für den Kurs brauchst, findest du im Intranet.","en":"Wszystko, czego potrzebujesz na kurs, znajdziesz w intranecie."},{"de":"Gibt es **etwas, was** ich für dich tun kann?","en":"Czy jest coś, co mogę dla ciebie zrobić?"},{"de":"Ich kaufe nur **das, was** ich wirklich brauche.","en":"Kupuję tylko to, czego naprawdę potrzebuję."},{"de":"Am Freitag haben wir frei, **was** mich sehr freut.","en":"W piątek mamy wolne, co mnie bardzo cieszy.","note":"*was* odnosi się do całego pierwszego zdania."}],"source":"was"}],"exceptions":[{"title":"Nazwy miejscowości: tylko wo","text":"Po nazwie miejsca bez rodzajnika, np. miasta (*Luzern*) lub większości krajów (*Italien*), używaj **wo**. Przyimek + zaimek tutaj nie działa. Z rodzajnikiem działa: *in der Schweiz, **in der** …*","examples":[{"de":"Ich arbeite in Luzern, **wo** auch meine Schwester wohnt.","en":"Pracuję w Lucernie, gdzie mieszka też moja siostra.","note":"Nie: *Luzern, in dem …*"}],"source":"wo"},{"title":"das Buch, was …: w mowie, nie w języku standardowym","text":["W mowie często słyszysz *was* po rzeczowniku rodzaju nijakiego: *das Buch, **was** ich lese*. To uchodzi za niestandardowe. W piśmie i na egzaminie używaj po rzeczowniku **das**: *das Buch, **das** ich lese*.","Po przymiotniku rodzaju nijakiego użytym jako rzeczownik, zwłaszcza w stopniu najwyższym, **was** jest normalne: *das Beste, **was** …* (najlepsze, co …)."],"examples":[{"de":"Das ist das Beste, **was** mir dieses Jahr passiert ist.","en":"To najlepsze, co mi się w tym roku przydarzyło."},{"de":"Das Geschenk, **das** du mir gegeben hast, gefällt mir sehr.","en":"Bardzo podoba mi się prezent, który mi dałeś.","note":"Po rzeczowniku *das Geschenk*: **das**, nie *was*."}],"source":"dasoderwas"},{"title":"Zdanie względne może stać w środku zdania głównego","text":"Jeśli rzeczownik stoi na początku, zdanie względne następuje tuż po nim, a zdanie główne ciągnie się dalej po drugim przecinku. Trzymaj zdanie względne obok jego rzeczownika. Między nimi może stać tylko ostatnia część czasownika: *Ich habe den Film gesehen, **den** du mir empfohlen hast.* (Widziałem film, który mi poleciłeś.)","examples":[{"de":"Die Sitzung, **die** um 9 Uhr beginnt, dauert zwei Stunden.","en":"Zebranie, które zaczyna się o 9, trwa dwie godziny."}],"source":"rel"}],"mistakes":[{"wrong":"Der Mann ich gestern getroffen habe, ist Arzt.","right":"Der Mann, **den** ich gestern getroffen habe, ist Arzt.","why":"Angielski może pominąć zaimek względny (*the man I met*). Niemiecki nigdy."},{"wrong":"die Kollegin, die ich geholfen habe","right":"die Kollegin, **der** ich geholfen habe","why":"*helfen* łączy się z celownikiem: celownik rodzaju żeńskiego to *der*. W angielskim, francuskim, włoskim i hiszpańskim czasownik „help” i jego odpowiedniki łączą się z dopełnieniem bliższym (*que j'ai aidée, che ho aiutato, a la que ayudé*), więc uczący się wybierają biernik *die*."},{"wrong":"Ich kenne den Mann, den in der Kantine arbeitet.","right":"Ich kenne den Mann, **der** in der Kantine arbeitet.","why":"Przypadek wynika ze zdania względnego, a nie ze zdania głównego. Tutaj mężczyzna jest podmiotem czasownika *arbeitet*: mianownik."},{"wrong":"die Kunden, mit die ich spreche","right":"die Kunden, mit **denen** ich spreche","why":"Celownik liczby mnogiej to *denen*, nie *die* ani *den*."},{"wrong":"das Buch, was ich lese","right":"das Buch, **das** ich lese","why":"Po rzeczowniku używaj *der, die, das*. *was* stoi po *alles, etwas, nichts, das*, po stopniu najwyższym, np. *das Beste*, albo po całym zdaniu."},{"wrong":"die Wohnung, die wir haben gemietet","right":"die Wohnung, die wir gemietet **haben**","why":"Odmieniony czasownik idzie na koniec zdania względnego. Angielski, francuski, włoski i hiszpański zachowują tu zwykły szyk."},{"wrong":"die Firma, die ich arbeite","right":"die Firma, **bei der** ich arbeite","why":"Przyimek nie może zniknąć ani przejść na koniec (po angielsku *the company I work for*). Stoi na początku: *bei der*."},{"wrong":"die Kollegin, dessen Mann in Basel arbeitet","right":"die Kollegin, **deren** Mann in Basel arbeitet","why":"*dessen / deren* zależą od właściciela (*die Kollegin*, rodzaj żeński), a nie od rzeczy posiadanej. Włoskie *il cui* i hiszpańskie *cuyo* zgadzają się z rzeczą posiadaną, więc to częsta pułapka."}],"examples":[{"de":"Wie heisst die Frau, **die** am Empfang arbeitet?","en":"Jak się nazywa kobieta, która pracuje w recepcji?"},{"de":"Das ist der Laptop, **den** ich vom Geschäft bekommen habe.","en":"To jest laptop, który dostałem z pracy."},{"de":"Der Zug, **mit dem** ich nach Bern fahre, ist immer voll.","en":"Pociąg, którym jeżdżę do Berna, jest zawsze pełny."},{"de":"Die Kinder, **denen** ich Nachhilfe gebe, sind sehr motiviert.","en":"Dzieci, którym daję korepetycje, są bardzo zmotywowane."},{"de":"Ich habe eine Nachbarin, **deren** Tochter in Lausanne studiert.","en":"Mam sąsiadkę, której córka studiuje w Lozannie."},{"de":"Das Team, **für das** ich arbeite, ist sehr international.","en":"Zespół, dla którego pracuję, jest bardzo międzynarodowy."},{"de":"Wir wohnen in einem Quartier, **wo** es viele Spielplätze gibt.","en":"Mieszkamy w dzielnicy, gdzie jest dużo placów zabaw."},{"de":"Alles, **was** im Kühlschrank ist, darfst du essen.","en":"Możesz zjeść wszystko, co jest w lodówce."},{"de":"Der Bus hatte zwanzig Minuten Verspätung, **was** in der Schweiz selten ist.","en":"Autobus miał dwadzieścia minut opóźnienia, co w Szwajcarii zdarza się rzadko."}],"later":"Zdania względne z **wer** i **was** bez rzeczownika przed nimi (*Wer zu spät kommt, muss warten.* – Kto przychodzi za późno, musi czekać. *Was du sagst, stimmt.* – To, co mówisz, jest prawdą.), formalny zaimek względny **welcher** (*der Kollege, welcher …*) i forma dopełniacza **derer** pojawią się na poziomie B2.","selfcheck":{"types":{"fill":{"label":"Uzupełnij lukę","instruction":"Wpisz brakujące słowo względne: *der, die, das, den, dem, denen, dessen, deren* albo *was* lub *wo*. Wpisz jedno słowo. Rodzaj i liczbę odczytaj z rzeczownika przed przecinkiem, a przypadek ze zdania względnego.","example":{"q":"Der Kurs, ___ ich besuche, ist am Abend.","a":"den","why":"*der Kurs* jest rodzaju męskiego, a *besuchen* łączy się z biernikiem: *ich besuche den Kurs*."}},"prep":{"label":"Przyimek + zaimek","instruction":"Przyimek jest podany w nawiasie. Wpisz przyimek i zaimek względny, w tej kolejności (dwa słowa).","example":{"q":"Die Firma, ___ ich arbeite, ist in Winterthur. (bei)","a":"bei der","why":"*bei* + celownik, *die Firma* jest rodzaju żeńskiego: *bei der*."}},"join":{"label":"Połącz zdania","instruction":"Połącz dwa zdania w jedno. Zamień drugie zdanie na zdanie względne i postaw je tuż po rzeczowniku, który opisuje. Napisz całe nowe zdanie.","example":{"q":"Ich habe einen Bruder. Er wohnt in Genf.","a":"Ich habe einen Bruder, der in Genf wohnt.","why":"*Er* jest podmiotem, więc mianownik rodzaju męskiego: *der*. Czasownik *wohnt* idzie na koniec."}}},"items":[{"type":"fill","q":"Der Mann, ___ dort am Fenster steht, ist mein Chef.","a":["der"],"why":"Mężczyzna jest podmiotem czasownika *steht*: mianownik rodzaju męskiego, *der*."},{"type":"fill","q":"Der Mann, ___ ich gestern angerufen habe, ist mein Chef.","a":["den"],"why":"*anrufen* łączy się z biernikiem: *ich habe den Mann angerufen*."},{"type":"fill","q":"Der Mann, ___ ich die Unterlagen gegeben habe, ist mein Chef.","a":["dem"],"why":"*geben* + celownik dla osoby: *ich habe dem Mann die Unterlagen gegeben*."},{"type":"fill","q":"Die Kunden, ___ wir eine E-Mail geschickt haben, haben noch nicht geantwortet.","a":["denen"],"why":"*schicken* + celownik dla osoby, liczba mnoga: *denen*, nie *die*."},{"type":"fill","q":"Ich kenne die Frau, ___ Auto vor unserem Haus steht.","a":["deren"],"why":"Właścicielem jest *die Frau* (rodzaj żeński): *deren*. *Auto* nie ma rodzajnika."},{"type":"fill","q":"Das ist das Haus, ___ meine Grosseltern gebaut haben.","a":["das"],"why":"Po rzeczowniku *das Haus*: *das*, biernik rodzaju nijakiego. Nie *was*, bo jest rzeczownik."},{"type":"fill","q":"Das ist das Dorf, ___ meine Grosseltern wohnen.","a":["wo","in dem"],"why":"Miejsce: *wo*. *in dem* też jest poprawne."},{"type":"fill","q":"Es gibt nichts, ___ ich lieber esse als Rösti.","a":["was","das"],"why":"Po *nichts*: *was*. *das* też jest poprawne, ale dużo rzadsze."},{"type":"prep","q":"Die Kollegen, ___ ich zu Mittag esse, sind sehr nett. (mit)","a":["mit denen"],"why":"*mit* + celownik liczby mnogiej: *denen*."},{"type":"prep","q":"Das Projekt, ___ wir gerade sprechen, ist sehr wichtig. (über)","a":["über das"],"why":"*sprechen über* + biernik, *das Projekt* jest rodzaju nijakiego: *über das*."},{"type":"join","q":"Das ist meine Kollegin. Ich gehe oft mit ihr joggen.","a":["Das ist meine Kollegin, mit der ich oft joggen gehe."],"why":"*mit* + celownik rodzaju żeńskiego: *mit der*. Odmieniony czasownik *gehe* idzie na koniec."},{"type":"join","q":"Der Bus hat Verspätung. Ich nehme ihn jeden Morgen.","a":["Der Bus, den ich jeden Morgen nehme, hat Verspätung."],"why":"*ihn* to biernik, więc *den*. Zdanie względne stoi tuż po *der Bus*, z przecinkiem po obu stronach."}]},"sources":[{"id":"formen","title":"grammis: Flexion der Pronomina (formy der, die, das, denen, dessen)","url":"https://grammis.ids-mannheim.de/kontrastive-grammatik/3673","note":"Tabela zaimka der/die/das, który według grammis ma te same formy co zaimek względny. Jako zaimek względny ma w dopełniaczu rodzaju żeńskiego i liczby mnogiej formę deren (zob. stronę o zdaniach przydawkowych)."},{"id":"rel","title":"grammis: Relativsätze mit den Pronomen der, die, das (zdania względne z der, die, das)","url":"https://grammis.ids-mannheim.de/progr@mm/6867"},{"id":"attribut","title":"grammis: Erweiterung von Nominalphrasen mit Attributsätzen (rodzaj od rzeczownika, przypadek ze zdania względnego; dessen, deren)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/1643"},{"id":"komma","title":"grammis: Komma bei Nebensätzen (przecinki przy zdaniach podrzędnych)","url":"https://grammis.ids-mannheim.de/rechtschreibung/6203"},{"id":"wo","title":"grammis: Relativsätze mit wo (zdania względne z wo)","url":"https://grammis.ids-mannheim.de/progr@mm/6868"},{"id":"was","title":"grammis: Relativsätze mit was (zdania względne z was)","url":"https://grammis.ids-mannheim.de/progr@mm/6869"},{"id":"dasoderwas","title":"grammis: Das Geheimnis, das oder was du mir verraten hast? (das czy was jako zaimek względny)","url":"https://grammis.ids-mannheim.de/fragen/131"}]},{"id":"weil-obwohl-deshalb-trotzdem","number":5,"added":"2026-11-07","level":"B1.1","title":"weil / obwohl / deshalb / trotzdem","title_en":"Przyczyny, skutki i niespodzianki: weil, denn, deshalb, obwohl, trotzdem","summary":"Podaj przyczynę (*weil, denn*), skutek (*deshalb*) albo coś zaskakującego (*obwohl, trotzdem*), z czasownikiem we właściwym miejscu.","purpose":["Te słowa łączą dwie myśli: **dlaczego** coś się dzieje (przyczyna), **co z tego wynika** (skutek) albo że coś się dzieje, **chociaż** można by oczekiwać czegoś odwrotnego (niespodzianka).","Używasz ich cały czas, żeby wyjaśniać, usprawiedliwiać się i argumentować: *Ich komme später, **weil** der Zug Verspätung hat.* Potrzebujesz ich w listach, dyskusjach i na egzaminie B1, z właściwym szykiem zdania."],"logic":["Najpierw wybierz **znaczenie**: przyczyna, skutek czy niespodzianka.","Przyczyna i skutek to dwie strony jednego związku. *Ich bin krank* (przyczyna) → *ich bleibe zu Hause* (skutek). **weil** i **denn** wprowadzają przyczynę; **deshalb** wprowadza skutek.","Niespodzianka działa tak samo: **obwohl** wprowadza przeszkodę (*obwohl ich krank bin*), **trotzdem** wprowadza zaskakujący skutek (*trotzdem gehe ich arbeiten*).","Potem **rodzaj słowa** decyduje, gdzie stoi czasownik. **weil** i **obwohl** przesuwają czasownik na **koniec**. **denn** stoi poza zdaniem (pozycja 0), więc dalej jest zwykły szyk: czasownik na pozycji 2.","**deshalb**, **deswegen**, **darum** i **trotzdem** to przysłówki. Na pozycji 1 **czasownik stoi zaraz po nich**: *Deshalb **bleibe** ich zu Hause.* Mogą też stać w środku zdania: *Ich bleibe **deshalb** zu Hause.*"],"rules":[{"title":"Ogólny obraz: oczekiwane czy nieoczekiwane?","text":["Zwykle przyczyna prowadzi do oczekiwanego skutku: *krank → zu Hause bleiben*. Użyj **weil / denn** dla przyczyny i **deshalb** dla skutku.","Czasem oczekiwany skutek **nie** następuje: *krank → trotzdem arbeiten*. Użyj **obwohl** dla przeszkody i **trotzdem** dla zaskakującego skutku."],"table":{"caption":"Które słowo? Co słowo wprowadza × oczekiwane czy nie","head":["","oczekiwane","nieoczekiwane"],"rows":[["wprowadza przyczynę lub przeszkodę","**weil**, **denn**","**obwohl**"],["wprowadza skutek","**deshalb** (*deswegen, darum*)","**trotzdem**"]]},"examples":[{"de":"Ich bleibe zu Hause, **weil** ich krank bin.","en":"Zostaję w domu, bo jestem chory."},{"de":"Ich bin krank. **Deshalb** bleibe ich zu Hause.","en":"Jestem chory. Dlatego zostaję w domu."},{"de":"Ich gehe zur Arbeit, **obwohl** ich krank bin.","en":"Idę do pracy, chociaż jestem chory."},{"de":"Ich bin krank. **Trotzdem** gehe ich zur Arbeit.","en":"Jestem chory. Mimo to idę do pracy."}],"source":"konzessiv"},{"title":"Przyczyna z weil: czasownik na końcu","text":["**weil** zaczyna zdanie podrzędne: odmieniony czasownik idzie na **koniec**. Gdy czasownik ma dwie części, odmieniona stoi ostatnia: *weil ich arbeiten **muss***.","Zdanie z *weil* może stać na początku. Wtedy zdanie główne **zaczyna się od swojego czasownika**. Samo zdanie z *weil* odpowiada też na pytanie *warum?*."],"examples":[{"de":"Ich komme heute später, **weil** der Zug Verspätung **hat**.","en":"Przyjdę dziś później, bo pociąg ma opóźnienie."},{"de":"**Weil** ich krank **bin**, **bleibe** ich zu Hause.","en":"Ponieważ jestem chory, zostaję w domu."},{"de":"Warum lernst du Deutsch? – **Weil** ich in der Schweiz arbeiten **möchte**.","en":"Dlaczego uczysz się niemieckiego? – Bo chciałbym pracować w Szwajcarii."}],"source":"weil"},{"title":"Przyczyna z denn: zwykły szyk zdania","text":"**denn** też podaje przyczynę, ale nie zmienia szyku zdania. Stoi na **pozycji 0**, między dwoma zdaniami, więc czasownik zostaje na **pozycji 2**, jak w każdym zwykłym zdaniu.","examples":[{"de":"Wir nehmen das Velo, **denn** die Parkplätze in der Stadt **sind** teuer.","en":"Jedziemy rowerem, bo parkingi w mieście są drogie."},{"de":"Ich komme nicht mit, **denn** ich **habe** keine Zeit.","en":"Nie idę z wami, bo nie mam czasu.","note":"Część z *denn* zawsze stoi po zdaniu, które wyjaśnia. Żeby podać przyczynę na początku albo odpowiedzieć na *Warum?*, użyj *weil*."}],"source":"denn"},{"title":"Skutek z deshalb, deswegen, darum","text":["**deshalb**, **deswegen** i **darum** znaczą to samo: *dlatego, więc*. Wprowadzają **skutek** i odnoszą się do przyczyny podanej wcześniej.","To przysłówki, więc liczą się jako jedna część zdania. Na pozycji 1 **czasownik stoi zaraz po nich**. Mogą też stać w środku zdania, po czasowniku."],"table":{"caption":"Dwa miejsca dla deshalb","head":["pozycja","przykład"],"rows":[["pozycja 1, czasownik zaraz po nim","Der Bus hatte Verspätung. **Deshalb bin** ich zu spät gekommen."],["w środku zdania, po czasowniku","Der Bus hatte Verspätung. Ich **bin deshalb** zu spät gekommen."]]},"examples":[{"de":"Mein Kollege ist krank. **Deshalb muss** ich seine Kunden anrufen.","en":"Mój kolega jest chory. Dlatego muszę zadzwonić do jego klientów."},{"de":"Die Miete ist hoch. Wir suchen **deswegen** eine kleinere Wohnung.","en":"Czynsz jest wysoki. Dlatego szukamy mniejszego mieszkania."},{"de":"Im Zug kann ich lesen. **Darum fahre** ich lieber mit dem Zug als mit dem Auto.","en":"W pociągu mogę czytać. Dlatego wolę jeździć pociągiem niż samochodem."}],"source":"adverb"},{"title":"Niespodzianka z obwohl: czasownik na końcu","text":"**obwohl** (chociaż) wprowadza **przeszkodę**: to, co powinno było zapobiec skutkowi. Działa jak *weil*: czasownik na **końcu**, a jeśli to zdanie stoi pierwsze, zdanie główne zaczyna się od swojego czasownika.","examples":[{"de":"Sie ist pünktlich gekommen, **obwohl** ihr Bus Verspätung **hatte**.","en":"Przyszła punktualnie, chociaż jej autobus miał opóźnienie."},{"de":"**Obwohl** ich seit drei Jahren in Bern **wohne**, **verstehe** ich Berndeutsch noch nicht gut.","en":"Chociaż od trzech lat mieszkam w Bernie, wciąż słabo rozumiem dialekt berneński."}],"source":"obwohl"},{"title":"Niespodzianka z trotzdem: czasownik zaraz po nim","text":"**trotzdem** (mimo to, jednak) wprowadza **zaskakujący skutek**. To przysłówek, jak *deshalb*: na pozycji 1 czasownik stoi zaraz po nim albo sam przysłówek stoi w środku zdania.","examples":[{"de":"Der Chef war gestern krank. **Trotzdem hat** er an der Sitzung teilgenommen.","en":"Szef był wczoraj chory. Mimo to wziął udział w zebraniu."},{"de":"Ich habe wenig geschlafen. Ich bin **trotzdem** fit.","en":"Mało spałem. Mimo to jestem w formie."}],"source":"trotzdem"},{"title":"trotz, obwohl, trotzdem: jedna myśl, trzy rodzaje słów","text":["Tę samą niespodziankę można wyrazić na trzy sposoby. **trotz** to przyimek i łączy się z **rzeczownikiem** w dopełniaczu (zob. temat o dopełniaczu). **obwohl** łączy się ze **zdaniem** z czasownikiem na końcu. **trotzdem** zaczyna **zdanie główne**, z czasownikiem zaraz po nim.","Przyczyny mają taką samą trójkę: **wegen** + rzeczownik, **weil** + zdanie, **deshalb** + zdanie główne."],"table":{"caption":"To samo znaczenie, inny szyk zdania","head":["słowo","rodzaj słowa","co po nim następuje","przykład"],"rows":[["**trotz**","przyimek","rzeczownik (dopełniacz)","**Trotz des Regens** gehen wir wandern."],["**obwohl**","spójnik","zdanie, czasownik na końcu","**Obwohl** es **regnet**, gehen wir wandern."],["**trotzdem**","przysłówek","czasownik zaraz po nim","Es regnet. **Trotzdem gehen** wir wandern."]]},"examples":[{"de":"**Trotz des Regens** gehen wir wandern.","en":"Mimo deszczu idziemy na wędrówkę."},{"de":"**Obwohl** es regnet, gehen wir wandern.","en":"Chociaż pada, idziemy na wędrówkę."},{"de":"Es regnet. **Trotzdem** gehen wir wandern.","en":"Pada. Mimo to idziemy na wędrówkę."}],"source":"trotzdem"}],"exceptions":[{"title":"weil z czasownikiem na pozycji 2: tylko w mowie","text":["W codziennej mowie często słyszysz *weil* z czasownikiem na pozycji 2, zwykle po krótkiej pauzie: *…, weil – ich hab keine Zeit.* W mowie jest to prawie tak częste jak czasownik na końcu, a grammis mówi, że nie jest to po prostu błąd.","W piśmie uznaje się to za błąd. W e-mailach, listach i na egzaminie stawiaj czasownik na końcu."],"examples":[{"de":"Ich komme nicht mit, weil ich hab keine Zeit. (gesprochen)","en":"Nie idę z wami, bo – nie mam czasu.","note":"*hab* to potoczna, skrócona forma *habe*."},{"de":"Ich komme nicht mit, **weil** ich keine Zeit **habe**. (geschrieben)","en":"Nie idę z wami, ponieważ nie mam czasu."}],"source":"verbstellung"},{"title":"trotzdem jako spójnik: lepiej tego unikać","text":"Możesz przeczytać lub usłyszeć *trotzdem* użyte jak *obwohl*, z czasownikiem na końcu: *trotzdem es regnet*. grammis zaznacza, że w języku standardowym się tego unika. Używaj *obwohl* w zdaniu podrzędnym, a *trotzdem* zostaw jako przysłówek.","examples":[{"de":"Trotzdem es regnet, gehen wir wandern. (avoid)","en":"Chociaż pada, idziemy na wędrówkę."},{"de":"**Obwohl** es regnet, gehen wir wandern. (standard)","en":"Chociaż pada, idziemy na wędrówkę."}],"source":"konzessiv"},{"title":"Obwohl, … żeby się poprawić","text":"W mowie *obwohl* z pauzą i zwykłym szykiem może poprawiać to, co właśnie powiedziałeś, jak angielskie „Although, actually …”. To osobne użycie; przy łączeniu dwóch myśli czasownik nadal idzie na koniec.","examples":[{"de":"Ich nehme das Auto. Obwohl – mit dem Zug bin ich schneller.","en":"Wezmę samochód. Chociaż nie – pociągiem będę szybciej."}],"source":"obwohl"}],"mistakes":[{"wrong":"Ich komme nicht, weil ich habe keine Zeit.","right":"Ich komme nicht, weil ich keine Zeit **habe**.","why":"*weil* przesuwa czasownik na koniec. Angielskie *because*, francuskie *parce que*, włoskie *perché* i hiszpańskie *porque* nie zmieniają szyku, więc łatwo o tym zapomnieć. Czasownik na pozycji 2 po *weil* występuje tylko w mowie."},{"wrong":"Deshalb ich bleibe zu Hause.","right":"Deshalb **bleibe ich** zu Hause.","why":"*deshalb* zajmuje pozycję 1, więc zaraz po nim stoi czasownik. Angielskie *so I stay* i francuskie *c'est pourquoi je reste* stawiają najpierw podmiot; niemiecki nie."},{"wrong":"Ich bin müde, trotzdem ich gehe joggen.","right":"Ich bin müde, trotzdem **gehe ich** joggen.","why":"*trotzdem* działa jak *deshalb*: czasownik stoi zaraz po nim."},{"wrong":"…, denn ich keine Zeit habe.","right":"…, denn ich **habe** keine Zeit.","why":"*denn* nie zmienia szyku: czasownik zostaje na pozycji 2. Spośród słów oznaczających przyczynę tylko *weil* przesuwa go na koniec."},{"wrong":"Denn ich krank war, bin ich zu Hause geblieben.","right":"**Weil** ich krank war, bin ich zu Hause geblieben.","why":"Część z *denn* nie może stać na początku. Żeby podać przyczynę na początku, użyj *weil*."},{"wrong":"Ich gehe joggen, trotzdem ich müde bin.","right":"Ich gehe joggen, **obwohl** ich müde bin.","why":"W zdaniu z czasownikiem na końcu użyj *obwohl*. Standardowy niemiecki unika *trotzdem* jako spójnika."},{"wrong":"Obwohl es regnet, wir gehen wandern.","right":"Obwohl es regnet, **gehen wir** wandern.","why":"Gdy zdanie z *obwohl* lub *weil* stoi na początku, zdanie główne zaczyna się od swojego czasownika. Angielski i francuski stawiają tu najpierw podmiot, więc to częsty błąd przeniesiony z innego języka."},{"wrong":"Ich habe viel gelernt. Trotzdem habe ich die Prüfung bestanden.","right":"Ich habe viel gelernt. **Deshalb** habe ich die Prüfung bestanden.","why":"Zdany egzamin to oczekiwany skutek nauki, więc pasuje *deshalb*. *trotzdem* służy tylko do niespodzianki: *Ich habe wenig gelernt. Trotzdem habe ich bestanden.*"}],"examples":[{"de":"Ich rufe dich später an, **weil** ich gerade in einer Sitzung bin.","en":"Zadzwonię do ciebie później, bo jestem teraz na zebraniu."},{"de":"Ich nehme einen Regenschirm mit, **denn** am Nachmittag soll es regnen.","en":"Biorę parasol, bo po południu ma padać."},{"de":"Die Kita schliesst um sechs. **Deshalb** muss ich pünktlich gehen.","en":"Żłobek zamyka się o szóstej. Dlatego muszę wyjść punktualnie."},{"de":"Ich hatte Fieber. Ich bin **deswegen** nicht zur Arbeit gegangen.","en":"Miałem gorączkę. Dlatego nie poszedłem do pracy."},{"de":"**Obwohl** die Wohnung klein ist, ist sie sehr teuer.","en":"Chociaż mieszkanie jest małe, jest bardzo drogie."},{"de":"Er spricht gut Deutsch, **obwohl** er erst seit einem Jahr hier lebt.","en":"On dobrze mówi po niemiecku, chociaż mieszka tu dopiero od roku."},{"de":"Das Wetter war schlecht. **Trotzdem** sind wir auf den Pilatus gefahren.","en":"Pogoda była zła. Mimo to wjechaliśmy na Pilatus."},{"de":"Ich mag meinen Job. **Darum** bleibe ich in der Firma.","en":"Lubię swoją pracę. Dlatego zostaję w firmie."}],"later":"Więcej spójników pojawi się później: *da* (ponieważ, skoro: formalne, czasownik na końcu), *daher* (= *deshalb*, bardziej formalne), *sodass* (tak że: skutek, czasownik na końcu), *dennoch* (= *trotzdem*, bardziej formalne) i *zwar … aber* (wprawdzie … ale).","selfcheck":{"types":{"choose":{"label":"Które słowo?","instruction":"Wpisz brakujące słowo: *weil*, *denn*, *deshalb*, *obwohl* albo *trotzdem*. Wpisz tylko jedno słowo. Skorzystaj z dwóch wskazówek: znaczenia (przyczyna, skutek czy niespodzianka) i miejsca czasownika (na końcu, na pozycji 2 albo zaraz po luce). Tam, gdzie pasuje *deshalb*, poprawne są też *deswegen* i *darum*.","example":{"q":"Ich trinke viel Wasser, ___ es heiss ist.","a":"weil","why":"Przyczyna, a czasownik *ist* stoi na końcu → *weil*."}},"join":{"label":"Połącz zdania","instruction":"Połącz dwa zdania słowem z nawiasu. Zmień szyk, jeśli to słowo tego wymaga, i użyj zaimka, jeśli rzeczownik się powtarza. Zdanie z *weil* lub *obwohl* może stać na początku albo na końcu; *denn* zawsze wprowadza drugie zdanie; *deshalb* i *trotzdem* mogą stać na pozycji 1 albo po czasowniku. Napisz całe nowe zdanie.","example":{"q":"Ich habe Hunger. Ich esse ein Sandwich. (deshalb)","a":"Ich habe Hunger, deshalb esse ich ein Sandwich.","why":"*deshalb* wprowadza skutek, a czasownik stoi zaraz po nim: *esse ich*."}}},"items":[{"type":"choose","q":"Ich mache einen Deutschkurs, ___ ich die B1-Prüfung bestehen will.","a":["weil"],"why":"Przyczyna, a czasownik (*will*) stoi na końcu → *weil*."},{"type":"choose","q":"Ich mache einen Deutschkurs, ___ ich will die B1-Prüfung bestehen.","a":["denn"],"why":"Przyczyna, ale czasownik (*will*) zostaje na pozycji 2 → *denn*."},{"type":"choose","q":"Ich will die B1-Prüfung bestehen. ___ mache ich einen Deutschkurs.","a":["Deshalb","Deswegen","Darum"],"why":"Kurs to skutek, a czasownik stoi zaraz po luce → *deshalb* (albo *deswegen*, *darum*)."},{"type":"choose","q":"___ es schon spät ist, arbeitet mein Chef noch.","a":["Obwohl"],"why":"Jest późno, więc można by oczekiwać, że szef skończy pracę: to przeszkoda. Czasownik (*ist*) stoi na końcu → *obwohl*."},{"type":"choose","q":"Es ist schon spät. ___ arbeitet mein Chef noch.","a":["Trotzdem"],"why":"Zaskakujący skutek, a czasownik stoi zaraz po luce → *trotzdem*."},{"type":"choose","q":"Es gab einen Stau. Ich bin ___ zu spät zur Sitzung gekommen.","a":["deshalb","deswegen","darum"],"why":"Spóźnienie to oczekiwany skutek korka → *deshalb*, tutaj w środku zdania."},{"type":"choose","q":"Er ist zur Arbeit gegangen, ___ er Fieber hatte.","a":["obwohl"],"why":"Gorączka powinna była zatrzymać go w domu: to przeszkoda. Czasownik (*hatte*) stoi na końcu → *obwohl*."},{"type":"join","q":"Das Restaurant ist teuer. Wir essen oft dort. (trotzdem)","a":["Das Restaurant ist teuer, trotzdem essen wir oft dort.","Das Restaurant ist teuer, wir essen trotzdem oft dort.","Das Restaurant ist teuer und trotzdem essen wir oft dort.","Das Restaurant ist teuer und wir essen trotzdem oft dort.","Das Restaurant ist teuer, trotzdem essen wir dort oft.","Das Restaurant ist teuer, wir essen dort trotzdem oft.","Das Restaurant ist teuer und trotzdem essen wir dort oft.","Das Restaurant ist teuer und wir essen dort trotzdem oft.","Das Restaurant ist teuer, aber trotzdem essen wir oft dort.","Das Restaurant ist teuer, aber wir essen trotzdem oft dort."],"why":"*trotzdem* wprowadza zaskakujący skutek; czasownik stoi zaraz po nim (*essen wir*) albo *trotzdem* stoi w środku zdania."},{"type":"join","q":"Ich kann nicht kommen. Ich muss arbeiten. (weil)","a":["Ich kann nicht kommen, weil ich arbeiten muss.","Weil ich arbeiten muss, kann ich nicht kommen."],"why":"*weil* przesuwa odmieniony czasownik (*muss*) na koniec, po *arbeiten*."},{"type":"join","q":"Ich nehme ein Taxi. Es ist schon sehr spät. (denn)","a":["Ich nehme ein Taxi, denn es ist schon sehr spät."],"why":"*denn* zachowuje zwykły szyk: *es ist …*, czasownik na pozycji 2. Część z *denn* stoi jako druga."},{"type":"join","q":"Wir nehmen die Wohnung. Die Wohnung ist teuer. (obwohl)","a":["Wir nehmen die Wohnung, obwohl sie teuer ist.","Obwohl die Wohnung teuer ist, nehmen wir sie.","Obwohl sie teuer ist, nehmen wir die Wohnung.","Wir nehmen die Wohnung, obwohl die Wohnung teuer ist."],"why":"*obwohl* wprowadza przeszkodę (*teuer*), z czasownikiem (*ist*) na końcu. Jeśli to zdanie stoi pierwsze, zdanie główne zaczyna się od *nehmen*."}]},"sources":[{"id":"konzessiv","title":"grammis: Konzessivsätze (zdania przyzwalające; w standardowym niemieckim unika się trotzdem jako spójnika)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/2109"},{"id":"weil","title":"grammis, słownik spójników: weil (spójnik podrzędny przyczynowy, czasownik na końcu)","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"grammis, słownik spójników: denn (przyczynowy, pozycja 0, czasownik zostaje na drugim miejscu)","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"adverb","title":"grammis: Nicht nacherstfähige Adverbkonnektoren (deshalb, darum, trotzdem: pozycja 1 lub środek zdania)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/1279"},{"id":"deshalb","title":"grammis, słownik spójników: deshalb (skutek; synonimy daher, deswegen)","url":"https://grammis.ids-mannheim.de/konnektoren/407094"},{"id":"deswegen","title":"grammis, słownik spójników: deswegen (skutek)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"darum","title":"grammis, słownik spójników: d(a)rum (skutek)","url":"https://grammis.ids-mannheim.de/konnektoren/407096"},{"id":"obwohl","title":"grammis, słownik spójników: obwohl (spójnik podrzędny przyzwalający, czasownik na końcu)","url":"https://grammis.ids-mannheim.de/konnektoren/406906"},{"id":"trotzdem","title":"grammis, słownik spójników: trotzdem (przysłówek przyzwalający; porównaj trotz + dopełniacz)","url":"https://grammis.ids-mannheim.de/konnektoren/406981"},{"id":"verbstellung","title":"grammis: Verbstellung nach weil, obwohl, wobei (czasownik na drugim miejscu w mowie)","url":"https://grammis.ids-mannheim.de/fragen/133"}]},{"id":"passiv-praesens","number":6,"added":"2026-11-07","level":"B1.1","title":"Passiv Präsens","title_en":"Strona bierna: co się robi, a nie kto to robi","summary":"Powiedz, co się dzieje, bez mówienia, kto to robi (*Das Altpapier **wird** am Dienstag **abgeholt**.*), także z czasownikami modalnymi (*Das Formular **muss** bis Freitag **ausgefüllt werden**.*).","purpose":["Strona bierna stawia w centrum **czynność**, a nie osobę, która ją wykonuje: *Das Altpapier **wird** am Dienstag **abgeholt**.* (Makulatura jest odbierana we wtorek.) Kto ją odbiera, nie ma znaczenia albo wszyscy to wiedzą.","Spotkasz ją w Szwajcarii wszędzie: w ogłoszeniach na klatce schodowej, formularzach, instrukcjach, kalendarzach odbioru odpadów, komunikatach SBB i e-mailach w pracy (*Die Rechnung **wird** morgen **verschickt**.*)."],"logic":["Strona bierna to **werden + Partizip II**. *werden* jest odmienione i stoi na pozycji 2. Partizip II idzie na **koniec**: *Die Heizung **wird** heute **repariert**.*","Przy zmianie ze strony czynnej na bierną **dopełnienie w bierniku staje się podmiotem** (mianownik): *Man repariert **den** Lift.* → **Der** *Lift wird repariert.*","Wykonawca czynności zwykle znika. Jeśli jest potrzebny, dodaj go za pomocą **von** + celownik: *vom Hauswart*.","Przy **czasowniku modalnym** to on stoi na pozycji 2, a **Partizip II + werden** idą na koniec: *Das Formular **muss** ausgefüllt **werden**.*","W zdaniu podrzędnym (*dass, weil, ob* …) odmieniony czasownik idzie na **sam koniec**: *…, dass das Formular ausgefüllt werden **muss**.*"],"rules":[{"title":"werden + Partizip II","text":"Odmień *werden* zgodnie z podmiotem i postaw Partizip II na końcu. Partizip II nigdy się nie zmienia.","table":{"caption":"Passiv Präsens czasownika fragen (pytać)","head":["","werden","przykład"],"rows":[["ich","**werde**","Ich **werde** oft **gefragt**."],["du","**wirst**","Du **wirst** oft **gefragt**."],["er / sie / es","**wird**","Sie **wird** oft **gefragt**."],["wir","**werden**","Wir **werden** oft **gefragt**."],["ihr","**werdet**","Ihr **werdet** oft **gefragt**."],["sie / Sie","**werden**","Sie **werden** oft **gefragt**."]]},"examples":[{"de":"Das Altpapier **wird** am Dienstag **abgeholt**.","en":"Makulatura jest odbierana we wtorek."},{"de":"Die Pakete **werden** morgen **geliefert**.","en":"Paczki będą dostarczone jutro."},{"de":"In diesem Büro **wird** Französisch **gesprochen**.","en":"W tym biurze mówi się po francusku."}],"source":"aktivpassiv"},{"title":"Ze strony czynnej na bierną: dopełnienie w bierniku staje się podmiotem","text":["Weź **dopełnienie w bierniku** ze zdania w stronie czynnej i zrób z niego **podmiot** (mianownik). *werden* zgadza się z tym nowym podmiotem: liczba pojedyncza *wird*, liczba mnoga *werden*.","Podmiot ze strony czynnej znika. Jeśli to *man*, znika zawsze. Dopełnienie w celowniku zostaje w celowniku: *Man hilft **den Kunden** sofort.* → **Den Kunden** *wird sofort geholfen.*"],"examples":[{"de":"**Der Lift wird** heute **repariert**.","en":"Winda jest dziś naprawiana.","note":"Strona czynna: *Man repariert **den Lift** heute.* Biernik *den Lift* → mianownik *der Lift*."},{"de":"**Die Rechnungen werden** am Monatsende **verschickt**.","en":"Faktury są wysyłane na koniec miesiąca.","note":"Strona czynna: *Wir verschicken die Rechnungen am Monatsende.* Podmiot w liczbie mnogiej, więc *werden*."}],"source":"subjekt"},{"title":"Wykonawca z von, środek lub przyczyna z durch","text":["Większość zdań w stronie biernej nie wymienia wykonawcy. Jeśli chcesz go wymienić, użyj **von** + celownik dla osoby lub instytucji, która wykonuje czynność: *von der Chefin, von der Gemeinde, vom Hauswart* (*vom* = *von dem*).","Dla **środka** lub **przyczyny** użyj **durch** + biernik: *durch eine Wärmepumpe, durch den Lärm*."],"examples":[{"de":"Die Sitzung **wird von der Chefin geleitet**.","en":"Zebranie jest prowadzone przez szefową."},{"de":"Die Lernenden **werden von einer erfahrenen Fachperson betreut**.","en":"Uczniowie zawodu są pod opieką doświadczonego fachowca."},{"de":"Die Wohnung **wird durch eine Wärmepumpe geheizt**.","en":"Mieszkanie jest ogrzewane pompą ciepła."},{"de":"Der Verkehr **wird durch die Baustelle behindert**.","en":"Ruch jest utrudniany przez roboty drogowe."}],"source":"agens"},{"title":"Strona bierna bez podmiotu: Hier wird nicht geraucht.","text":["Niektóre zdania w stronie biernej w ogóle **nie mają podmiotu**. Mówią, co ludzie ogólnie robią (lub czego nie robią), często z czasownikami użytymi bez dopełnienia: *arbeiten, rauchen, essen, tanzen, lachen*. *werden* ma zawsze formę **wird**.","Jeśli na pozycji 1 nie stoi nic innego, wypełnia ją **es**: *Es wird viel gelacht.* Jeśli na pozycji 1 stoi inne słowo, *es* znika: *Bei uns wird viel gelacht.*"],"examples":[{"de":"Hier **wird** nicht **geraucht**.","en":"Tu się nie pali."},{"de":"Am Sonntag **wird** nicht **gearbeitet**.","en":"W niedzielę się nie pracuje."},{"de":"In unserem Team **wird** viel **gelacht**.","en":"W naszym zespole dużo się śmieje."},{"de":"**Es wird** um 12 Uhr **gegessen**.","en":"Je się o 12."}],"source":"subjektlos"},{"title":"Strona bierna z czasownikami modalnymi: muss … ausgefüllt werden","text":"**Czasownik modalny** (*muss, kann, darf, soll*) jest odmieniony i stoi na pozycji 2. Na końcu stoją **Partizip II**, a potem **werden** (bezokolicznik, nigdy się nie zmienia). Tej konstrukcji ogłoszenia i formularze używają cały czas.","examples":[{"de":"Das Formular **muss** bis Freitag **ausgefüllt werden**.","en":"Formularz musi zostać wypełniony do piątku."},{"de":"Velos **dürfen** hier nicht **abgestellt werden**.","en":"Rowerów nie wolno tu parkować."},{"de":"Der Termin **kann** auch online **verschoben werden**.","en":"Termin można też przesunąć online."},{"de":"Hunde **müssen** an der Leine **geführt werden**.","en":"Psy muszą być prowadzone na smyczy."}],"source":"modal"},{"title":"W zdaniu podrzędnym odmieniony czasownik idzie na koniec","text":"Po *dass, weil, ob, wenn* i w zdaniach względnych cała grupa czasownika idzie na koniec, a **odmieniony** czasownik jest ostatnim słowem: *… repariert **wird***, *… ausgefüllt werden **muss***.","examples":[{"de":"Wir informieren Sie, dass das Wasser am Montag **abgestellt wird**.","en":"Informujemy Państwa, że w poniedziałek woda zostanie wyłączona."},{"de":"Weisst du, ob das Paket heute **geliefert wird**?","en":"Wiesz, czy paczka zostanie dziś dostarczona?"},{"de":"Bitte beachten Sie, dass der Antrag **unterschrieben werden muss**.","en":"Prosimy pamiętać, że wniosek musi zostać podpisany."}],"source":"klammer"}],"exceptions":[{"title":"ist geöffnet (stan) czy wird geöffnet (czynność)?","text":["**sein + Partizip II** opisuje **stan**, czyli wynik czynności: *Der Laden **ist** geöffnet.* (Sklep jest otwarty.) Nazywa się to *Zustandspassiv*.","**werden + Partizip II** opisuje samą **czynność**, czyli to, co się dzieje: *Die Türen **werden** um 19 Uhr **geöffnet**.* (Drzwi są otwierane o 19.)"],"examples":[{"de":"Die Post **ist** am Samstag bis 12 Uhr **geöffnet**.","en":"Poczta jest w sobotę otwarta do 12.","note":"Godziny otwarcia: stan, więc *ist*."},{"de":"Die Türen **werden** um 19 Uhr **geöffnet**.","en":"Drzwi są otwierane o 19.","note":"Ktoś otwiera je w tym momencie: czynność, więc *werden*."},{"de":"Das Formular **ist** schon **ausgefüllt**.","en":"Formularz jest już wypełniony.","note":"Czynność się zakończyła; to jest jej wynik."}],"source":"zustand"},{"title":"werden ma trzy funkcje","text":["**werden + Partizip II** = strona bierna: *Ich werde morgen **angerufen**.* (Jutro ktoś do mnie zadzwoni.)","**werden + bezokolicznik** = czas przyszły: *Ich werde morgen **anrufen**.* (Jutro zadzwonię.)","Samo **werden** = stawać się: *Sie wird Pflegefachfrau.* (Ona zostanie pielęgniarką.)","Gdy więc *werden* jest odmienionym czasownikiem, spójrz na czasownik na końcu: Partizip II (*gemacht*) oznacza stronę bierną, bezokolicznik (*machen*) oznacza czas przyszły."],"examples":[{"de":"Die Heizung **wird** morgen **repariert**.","en":"Ogrzewanie zostanie jutro naprawione.","note":"Strona bierna: Partizip II."},{"de":"Der Techniker **wird** morgen **kommen**.","en":"Technik przyjdzie jutro.","note":"Czas przyszły: bezokolicznik."}],"source":"hilfsverb"}],"mistakes":[{"wrong":"Das Formular muss werden ausgefüllt.","right":"Das Formular muss **ausgefüllt werden**.","why":"Angielskie *must be filled in*, francuskie *doit être rempli*, włoskie *deve essere compilato* i hiszpańskie *debe ser rellenado* stawiają „być” na pierwszym miejscu, przed imiesłowem. Niemiecki stawia *werden* na końcu."},{"wrong":"Das Formular muss bis Freitag ausgefüllt.","right":"Das Formular muss bis Freitag ausgefüllt **werden**.","why":"Z czasownikiem modalnym strona bierna nadal potrzebuje *werden* na końcu."},{"wrong":"Die Briefe sind jeden Tag verteilt.","right":"Die Briefe **werden** jeden Tag verteilt.","why":"Czynność, która się dzieje, wymaga *werden*. Angielskie *are*, francuskie *sont*, włoskie *sono* i hiszpańskie *son* skłaniają do użycia *sind*, ale *sein* + Partizip II opisuje tylko stan."},{"wrong":"Die Sitzung wird bei der Chefin geleitet.","right":"Die Sitzung wird **von** der Chefin geleitet.","why":"*bei* brzmi jak angielskie *by*, ale znaczy „przy” albo „u”. Wykonawcę wprowadza *von*."},{"wrong":"Die Sitzung wird von die Chefin geleitet.","right":"Die Sitzung wird von **der** Chefin geleitet.","why":"*von* zawsze łączy się z celownikiem. (*durch* łączy się z biernikiem: *durch den Lärm*.)"},{"wrong":"Den Lift wird repariert.","right":"**Der** Lift wird repariert.","why":"Dopełnienie w bierniku ze strony czynnej staje się podmiotem, więc zmienia się na mianownik."},{"wrong":"Hier werden nicht geraucht.","right":"Hier **wird** nicht geraucht.","why":"Strona bierna bez podmiotu ma zawsze *wird*, formę liczby pojedynczej."},{"wrong":"…, dass das Formular muss ausgefüllt werden.","right":"…, dass das Formular ausgefüllt werden **muss**.","why":"W zdaniu z *dass* odmieniony czasownik (modalny) idzie na sam koniec."}],"examples":[{"de":"Glas **wird** nach Farben **getrennt**.","en":"Szkło sortuje się według kolorów."},{"de":"Die Reisenden **werden gebeten**, in Fahrtrichtung rechts auszusteigen.","en":"Podróżnych prosi się o wysiadanie po prawej stronie w kierunku jazdy."},{"de":"In Schweizer Zügen **wird** nicht **geraucht**.","en":"W szwajcarskich pociągach się nie pali."},{"de":"Die Mitarbeitenden **werden** per E-Mail **informiert**.","en":"Pracownicy są informowani e-mailem."},{"de":"Leere Batterien **können** im Laden **abgegeben werden**.","en":"Zużyte baterie można oddać w sklepie."},{"de":"Die Steuererklärung **muss** bis Ende März **eingereicht werden**.","en":"Zeznanie podatkowe musi zostać złożone do końca marca."},{"de":"Ich habe gehört, dass das Büro im Januar **renoviert wird**.","en":"Słyszałem, że biuro będzie remontowane w styczniu."},{"de":"Der Laden **ist** am Sonntag **geschlossen**.","en":"Sklep jest w niedzielę zamknięty.","note":"Stan: *sein* + Partizip II."}],"later":"**Strona bierna w czasie Präteritum**: *wurde* + Partizip II, do mówienia o przeszłości (*Das Schulhaus **wurde** 1905 **gebaut**.* – Budynek szkoły został zbudowany w 1905 roku.). Spotkasz ją w tekstach o przeszłości. **Strona bierna w czasie Perfekt** (*ist gebaut worden*) i strona bierna z *bekommen* (*Ich bekomme das Paket geliefert.* – Paczka zostanie mi dostarczona.) pojawią się w jednej z kolejnych lekcji.","selfcheck":{"types":{"choose":{"label":"wird, werden czy ist?","instruction":"Wybierz słowo z nawiasu, które pasuje do luki. Wpisz jedno słowo.","example":{"q":"Das Museum ___ heute bis 20 Uhr geöffnet. (wird / ist)","a":"ist","why":"Godziny otwarcia opisują stan: *ist geöffnet*."}},"end":{"label":"Uzupełnij koniec zdania","instruction":"Zamień czasownik z nawiasu na stronę bierną (Präsens). Wpisz wszystkie słowa, które idą do luki, we właściwej kolejności. Jeśli w nawiasie jest czasownik modalny, użyj go też, we właściwej formie.","example":{"q":"Ich hoffe, dass mein Velo bald ___ (reparieren).","a":"repariert wird","why":"Strona bierna: *repariert* + *wird*. W zdaniu z *dass* odmieniony czasownik idzie na koniec."}},"rewrite":{"label":"Strona czynna → bierna","instruction":"Przepisz zdanie w stronie biernej (Präsens). Jeśli podmiotem w stronie czynnej jest *man*, pomiń go. Każdego innego wykonawcę dodaj z *von*. Napisz całe zdanie.","example":{"q":"Man repariert die Strasse.","a":"Die Strasse wird repariert.","why":"*die Strasse* staje się podmiotem; *man* znika."}},"which":{"label":"Strona bierna czy czas przyszły?","instruction":"Czy *werden* jest w tym zdaniu użyte dla strony biernej, czy dla czasu przyszłego? Wpisz **Passiv** albo **Futur**.","example":{"q":"Ich werde dich morgen anrufen.","a":"Futur","why":"*werden* + bezokolicznik (*anrufen*) = czas przyszły (**Futur**)."}}},"items":[{"type":"choose","q":"Das Altpapier ___ jeden zweiten Dienstag abgeholt. (wird / ist)","a":["wird"],"why":"Coś, co dzieje się regularnie, to czynność: *wird abgeholt*."},{"type":"choose","q":"Keine Sorge, das Formular ___ schon ausgefüllt. Ich habe es gestern gemacht. (wird / ist)","a":["ist"],"why":"Formularz wypełniono wczoraj; teraz to stan, czyli wynik: *ist ausgefüllt*."},{"type":"choose","q":"Die Briefe ___ jeden Morgen verteilt. (wird / werden)","a":["werden"],"why":"*die Briefe* to liczba mnoga, więc *werden*."},{"type":"end","q":"Velos dürfen im Treppenhaus nicht ___ (abstellen).","a":["abgestellt werden"],"why":"Czasownik modalny na pozycji 2, potem Partizip II + *werden* na końcu."},{"type":"end","q":"Im Brief steht, dass die Miete bis Ende Monat ___ (bezahlen, müssen).","a":["bezahlt werden muss"],"why":"W zdaniu z *dass*: Partizip II, *werden* i odmieniony czasownik modalny *muss* na samym końcu."},{"type":"end","q":"Weisst du, ob die Pakete heute ___ (liefern)?","a":["geliefert werden"],"why":"*die Pakete* to liczba mnoga: *werden*, na końcu z powodu *ob*."},{"type":"rewrite","q":"Man sammelt die Batterien im Laden.","a":["Die Batterien werden im Laden gesammelt.","Im Laden werden die Batterien gesammelt."],"why":"*die Batterien* staje się podmiotem (liczba mnoga, więc *werden*); *man* znika."},{"type":"rewrite","q":"Der Hauswart repariert die Waschmaschine.","a":["Die Waschmaschine wird vom Hauswart repariert.","Die Waschmaschine wird von dem Hauswart repariert.","Vom Hauswart wird die Waschmaschine repariert."],"why":"Wykonawca czynności pojawia się znowu z *von* + celownikiem: *vom Hauswart*."},{"type":"rewrite","q":"Man muss den Antrag online ausfüllen.","a":["Der Antrag muss online ausgefüllt werden.","Online muss der Antrag ausgefüllt werden."],"why":"*den Antrag* zmienia się w *der Antrag* (mianownik). Czasownik modalny + Partizip II + *werden*."},{"type":"rewrite","q":"Man arbeitet am Sonntag nicht.","a":["Am Sonntag wird nicht gearbeitet.","Es wird am Sonntag nicht gearbeitet."],"why":"Brak dopełnienia, więc brak podmiotu: *wird* + Partizip II, z *es* tylko wtedy, gdy pozycja 1 jest pusta."},{"type":"which","q":"Der Techniker wird am Montag kommen.","a":["Futur"],"why":"*werden* + bezokolicznik (*kommen*) = czas przyszły (**Futur**)."},{"type":"which","q":"Die Heizung wird am Montag repariert.","a":["Passiv"],"why":"*werden* + Partizip II (*repariert*) = strona bierna (**Passiv**)."}]},"sources":[{"id":"aktivpassiv","title":"grammis: Aktiv und Passiv (strona czynna i bierna: werden + Partizip II)","url":"https://grammis.ids-mannheim.de/progr@mm/6723"},{"id":"subjekt","title":"grammis: Werden-Passiv mit Subjekt (dopełnienie w bierniku staje się podmiotem)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/930"},{"id":"agens","title":"grammis: Die Formulierung der Agens-Rolle in Aktiv- und Passivsätzen (wykonawca z von lub durch)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/1361"},{"id":"praep","title":"grammis: Präpositionalphrase (von + celownik, durch + biernik)","url":"https://grammis.ids-mannheim.de/kontrastive-grammatik/5747"},{"id":"subjektlos","title":"grammis: Subjektloses werden-Passiv (strona bierna bez podmiotu)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/1068"},{"id":"modal","title":"grammis: Fehlende Passivierbarkeit (czasowniki modalne z bezokolicznikiem strony biernej)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/1616"},{"id":"klammer","title":"grammis: Wortstellung in der Satzklammer (kolejność czasowników na końcu zdania)","url":"https://grammis.ids-mannheim.de/progr@mm/6840"},{"id":"zustand","title":"grammis: Vertiefung: sein-Passiv (stan: ist geöffnet)","url":"https://grammis.ids-mannheim.de/progr@mm/6724"},{"id":"hilfsverb","title":"grammis: Hilfsverben im Verbalkomplex (werden dla czasu przyszłego i dla strony biernej)","url":"https://grammis.ids-mannheim.de/kontrastive-grammatik/5856"},{"id":"werdenpassiv","title":"grammis: Werden-Passiv (formy we wszystkich czasach, np. wurde verhaftet)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/929"}]},{"id":"genitiv","number":7,"added":"2026-11-06","level":"B1.1","title":"Genitiv","title_en":"Dopełniacz: czyje to jest?","summary":"Pokaż, do kogo coś należy (*das Büro des Chefs*), i używaj *wegen, trotz, während, statt* w tekstach pisanych.","purpose":["Dopełniacz pokazuje, że coś **należy do** kogoś lub czegoś: *das Büro **des Chefs*** (biuro szefa), *der Sitz **der Firma*** (siedziba firmy).","W mowie potocznej często mówi się zamiast tego *von* + celownik: *das Büro **vom Chef***. Dopełniacz i tak jest ci potrzebny do czytania, e-maili, oficjalnych wypowiedzi i egzaminu B1, a także po kilku przyimkach, takich jak *wegen* (z powodu) i *trotz* (mimo)."],"logic":["Fraza w dopełniaczu stoi **po** rzeczowniku, który opisuje: *das Auto **meiner Schwester*** (dosłownie: samochód mojej siostry). Angielskie *'s* działa odwrotnie.","Tylko **imiona** stoją przed rzeczownikiem: *Annas Wohnung* (mieszkanie Anny). Nie ma apostrofu.","Sygnał niesie głównie **rodzajnik**. Rodzaj męski i nijaki mają **des / eines**, a rzeczownik dostaje **-s** lub **-es**. Rodzaj żeński i liczba mnoga mają **der**, a rzeczownik się nie zmienia.","Tak więc *der* ma teraz trzecią funkcję: mianownik rodzaju męskiego, celownik rodzaju żeńskiego i **dopełniacz rodzaju żeńskiego lub liczby mnogiej**. Którą z nich pełni, podpowiada miejsce w zdaniu.","Słowo pytające to **wessen?** (czyj?). W mowie częściej mówi się *wem gehört …?* (do kogo należy …?)."],"rules":[{"title":"Rodzajniki i zaimki w dopełniaczu","text":"Naucz się czterech kolumn jako wzoru: **des / des / der / der**. Zaimki dzierżawcze (*mein, dein, unser* …) i *kein* odmieniają się jak *ein*. Liczba mnoga nie ma rodzajnika nieokreślonego, więc używasz wtedy *von* + celownik (zob. Wyjątki).","table":{"caption":"Formy dopełniacza","head":["","rodzaj męski","rodzaj nijaki","rodzaj żeński","liczba mnoga"],"rows":[["rodzajnik określony","**des** Chef**s**","**des** Kind**es**","**der** Firma","**der** Kunden"],["rodzajnik nieokreślony","**eines** Chef**s**","**eines** Kind**es**","**einer** Firma","—"],["zaimek dzierżawczy","**meines** Chef**s**","**meines** Kind**es**","**meiner** Firma","**meiner** Kunden"],["przeczenie","**keines** Chef**s**","**keines** Kind**es**","**keiner** Firma","**keiner** Kunden"]]},"examples":[{"de":"Das ist das Büro **des Chefs**.","en":"To jest biuro szefa."},{"de":"Die Mitarbeitenden **der Firma** arbeiten oft im Homeoffice.","en":"Pracownicy firmy często pracują z domu."},{"de":"Die Wünsche **unserer Kunden** sind uns wichtig.","en":"Życzenia naszych klientów są dla nas ważne."}],"source":"kasus"},{"title":"Rzeczowniki rodzaju męskiego i nijakiego dostają -s lub -es","text":["Użyj **-es** po głosce s (*-s, -ss, -z, -tz, -x*): *des Hauses, des Platzes, des Fusses*. Rzeczowniki na *-nis* podwajają s: *des Ergebnisses*.","Użyj **-s** po *-el, -en, -er, -chen, -ling* i po samogłosce: *des Computers, des Mädchens, des Autos*.","Wiele rzeczowników jednosylabowych dopuszcza obie formy, a **-es** brzmi bardziej oficjalnie: *des Tages* (dużo częstsze niż *des Tags*), *des Kindes* lub *des Kinds*."],"examples":[{"de":"Am Ende **des Monats** bekomme ich meinen Lohn.","en":"Pod koniec miesiąca dostaję wypłatę."},{"de":"Die Ergebnisse **des Projekts** sind sehr gut.","en":"Wyniki projektu są bardzo dobre.","note":"*des Projektes* też jest poprawne."},{"de":"Die Miete **des Hauses** ist gestiegen.","en":"Czynsz za ten dom wzrósł."}],"source":"s-es"},{"title":"Słabe rzeczowniki rodzaju męskiego dostają -n lub -en, nigdy -s","text":"Grupa rzeczowników rodzaju męskiego, prawie zawsze oznaczających osoby lub zwierzęta, kończy się na **-(e)n** we wszystkich przypadkach oprócz mianownika: *der Kollege → des Kollegen*. Typowe końcówki to *-e* (*Kollege, Kunde, Junge*), *-ent* i *-ant* (*Student, Praktikant*), *-ist* (*Polizist*), a do tego *Mensch, Herr* (*des Herrn*) i *Nachbar*.","examples":[{"de":"Ich habe die Telefonnummer **des Kunden** nicht.","en":"Nie mam numeru telefonu klienta."},{"de":"Das ist der Laptop **meines Kollegen**.","en":"To jest laptop mojego kolegi z pracy."}],"source":"weak"},{"title":"Imiona stoją z przodu i dostają -s","text":"Postaw imię przed rzeczownikiem i dodaj **-s**, bez apostrofu: *Peters Büro*. Jeśli imię już kończy się głoską s (*-s, -ss, -z, -x*), napisz tylko apostrof: *Thomas' Auto*, *Max' Fahrrad*. Rzeczownik po imieniu nie ma rodzajnika.","examples":[{"de":"**Wessen** Jacke ist das? – Das ist **Marias** Jacke.","en":"Czyja to kurtka? – To kurtka Marii."},{"de":"**Thomas'** Präsentation war am besten.","en":"Prezentacja Thomasa była najlepsza."}],"source":"s-es"},{"title":"Przyimki z dopełniaczem","text":"Te przyimki łączą się w tekstach pisanych z dopełniaczem: **wegen** (z powodu), **trotz** (mimo), **während** (podczas), **statt** (zamiast), **innerhalb** (w ciągu, wewnątrz) i **ausserhalb** (poza).","examples":[{"de":"**Wegen einer Störung** fahren heute keine Züge nach Bern.","en":"Z powodu awarii dziś nie jeżdżą żadne pociągi do Berna."},{"de":"**Trotz des schlechten Wetters** gehen wir am Wochenende wandern.","en":"Mimo złej pogody idziemy w weekend na wędrówkę.","note":"Po rodzajniku przymiotniki w dopełniaczu kończą się na **-en**: *des schlechten Wetters*."},{"de":"**Während der Sitzung** bitte keine Handys.","en":"Podczas zebrania proszę bez telefonów komórkowych."},{"de":"**Statt eines Taxis** nehmen wir das Tram.","en":"Zamiast taksówki pojedziemy tramwajem."},{"de":"**Innerhalb einer Woche** bekommen Sie eine Antwort.","en":"W ciągu tygodnia dostanie Pan / Pani odpowiedź."}],"source":"prep"}],"exceptions":[{"title":"wegen + celownik w mowie","text":["W mowie wiele osób mówi *wegen **dem** Regen* zamiast *wegen **des** Regens*. To bardzo rozpowszechnione i w mowie prawie nie uważa się tego za błąd, ale w piśmie *wegen des Regens* jest wciąż dużo częstsze i to bezpieczny wybór. *Trotz* mocniej trzyma się dopełniacza.","Z zaimkami normalny jest celownik: *wegen mir* (z mojego powodu). Stara forma *meinetwegen* znaczy dziś najczęściej „niech będzie, nie mam nic przeciwko”."],"examples":[{"de":"Wegen **dem** Regen sind wir zu Hause geblieben. (gesprochen)","en":"Z powodu deszczu zostaliśmy w domu."},{"de":"Wegen **des Regens** sind wir zu Hause geblieben. (geschrieben)","en":"Z powodu deszczu zostaliśmy w domu."},{"de":"Kommst du **wegen mir**? – Ja, **meinetwegen**.","en":"Przychodzisz z mojego powodu? – Tak, niech będzie.","note":"Tutaj *meinetwegen* znaczy „niech będzie”."}],"source":"wegen"},{"title":"Liczba mnoga bez rodzajnika: użyj von + celownik","text":"Rzeczownik w liczbie mnogiej bez rodzajnika i przymiotnika w ogóle nie pokazuje dopełniacza, dlatego niemiecki używa zamiast niego *von* + celownik.","examples":[{"de":"die Meinung **von Experten**","en":"opinia ekspertów"},{"de":"Die Preise **von Wohnungen** in Zürich sind sehr hoch.","en":"Ceny mieszkań w Zurychu są bardzo wysokie."}],"source":"wegen"},{"title":"Niektóre rzeczowniki dostają -ns","text":"Kilka rzeczowników rodzaju męskiego zakończonych na *-e* dostaje w dopełniaczu **-ns**: *der Name → des Namens*, *der Gedanke → des Gedankens*, *der Glaube → des Glaubens*.","examples":[{"de":"Die Schreibweise **des Namens** ist falsch.","en":"Pisownia nazwiska jest błędna."}],"source":"weak"},{"title":"Niektóre wyrazy obce i skróty nie mają końcówki","text":"Wyrazy obce z nieakcentowaną końcówką *-us* lub *-as* zwykle się nie zmieniają: *des Zirkus, des Atlas*. Skróty mogą nie mieć końcówki: *des LKW* lub *des LKWs*. Nigdy nie stawiaj apostrofu w miejsce brakującej końcówki: *des Atlas'* jest błędne.","examples":[{"de":"die Fahrerin **des LKW**","en":"kierowczyni ciężarówki"}],"source":"s-es"},{"title":"Rzeczowniki rodzaju żeńskiego nigdy nie dostają końcówki","text":"W dopełniaczu przy rzeczownikach rodzaju żeńskiego zmienia się tylko rodzajnik: *die Firma → der Firma*, nigdy *der Firmas*.","examples":[{"de":"die Adresse **der Bank**","en":"adres banku"}],"source":"kasus"}],"mistakes":[{"wrong":"das Büro der Chef","right":"das Büro **des Chefs**","why":"Rodzaj męski: *des* plus *-s* przy rzeczowniku."},{"wrong":"Anna's Wohnung","right":"**Annas** Wohnung","why":"W niemieckim nie ma apostrofu przed *-s*. Apostrof to nawyk z angielskiego."},{"wrong":"des Kollegens","right":"des **Kollegen**","why":"Słabe rzeczowniki dostają *-n*, nigdy *-s*."},{"wrong":"der Firmas","right":"der **Firma**","why":"Rzeczowniki rodzaju żeńskiego nigdy nie dostają końcówki dopełniacza."},{"wrong":"mein Bruders Auto","right":"das Auto **meines Bruders**","why":"Tylko imiona stoją przed rzeczownikiem. Wszystko inne stoi po nim, inaczej niż w angielskim *my brother's car*."},{"wrong":"trotz dem Regen (in einem E-Mail)","right":"trotz **des Regens**","why":"W piśmie używaj dopełniacza po *trotz* i *wegen*."},{"wrong":"Wegen ich krank bin, bleibe ich zu Hause.","right":"**Weil** ich krank bin, bleibe ich zu Hause.","why":"*wegen* to przyimek: po nim stoi rzeczownik (*wegen **meiner Krankheit***). Przed zdaniem z czasownikiem użyj *weil*."},{"wrong":"Trotz es regnet, gehen wir wandern.","right":"**Obwohl** es regnet, … / **Trotz des Regens** …","why":"*trotz* łączy się z rzeczownikiem w dopełniaczu. Przed zdaniem z czasownikiem użyj *obwohl*."},{"wrong":"trotz des schlechtes Wetters","right":"trotz des **schlechten** Wetters","why":"Po *des* lub *der* w dopełniaczu przymiotnik zawsze kończy się na *-en*."}],"examples":[{"de":"Der Sitz **der Firma** ist in Zürich.","en":"Siedziba firmy jest w Zurychu."},{"de":"Kennst du die Freundin **meines Bruders**?","en":"Znasz dziewczynę mojego brata?"},{"de":"Die Farbe **des Autos** gefällt mir nicht.","en":"Nie podoba mi się kolor tego samochodu."},{"de":"**Wegen der Baustelle** brauche ich zehn Minuten länger.","en":"Z powodu robót drogowych potrzebuję dziesięciu minut więcej."},{"de":"**Während der Ferien** ist das Büro geschlossen.","en":"Podczas ferii biuro jest zamknięte."},{"de":"Der Name **des Hotels** ist schwierig.","en":"Nazwa hotelu jest trudna."},{"de":"Wir wohnen **ausserhalb der Stadt**.","en":"Mieszkamy poza miastem."},{"de":"Das ist der Hund **unserer Nachbarn**.","en":"To pies naszych sąsiadów."}],"later":"Pełne omówienie dopełniacza z przymiotnikami (*trotz starken Regens*, *wegen guter Arbeit*) przyjdzie razem z tematem o końcówkach przymiotników.","selfcheck":{"types":{"fill":{"label":"Uzupełnij lukę","instruction":"Wstaw wyrazy z nawiasu w dopełniaczu. Napisz całą frazę: rodzajnik (lub zaimek) plus rzeczownik.","example":{"q":"Das ist das Handy ___ (mein Vater).","a":"meines Vaters","why":"Rodzaj męski: *meines* plus *-s* przy rzeczowniku."}},"rewrite":{"label":"Mowa → pismo","instruction":"Zamień potoczną frazę z *von* albo z celownikiem na dopełniacz, którego używa się w piśmie.","example":{"q":"die Tür von dem Zimmer","a":"die Tür des Zimmers","why":"Rodzaj nijaki: *des* plus *-s*."}},"choose":{"label":"Przyimek czy spójnik?","instruction":"Wybierz z nawiasu pasujące słowo i napisz tylko to słowo. Po przyimku (*wegen, trotz*) stoi rzeczownik; po spójniku (*weil, obwohl*) stoi zdanie z czasownikiem na końcu.","example":{"q":"Ich bleibe heute zu Hause, ___ es regnet. (wegen / weil)","a":"weil","why":"Dalej stoi zdanie z czasownikiem (*regnet*), więc potrzebujesz spójnika *weil*."}}},"items":[{"type":"fill","q":"Die Adresse ___ (die Schule) steht auf der Website.","a":["der Schule"],"why":"Rodzaj żeński: *der*, bez końcówki przy rzeczowniku."},{"type":"fill","q":"Das ist der Schreibtisch ___ (unser Praktikant).","a":["unseres Praktikanten"],"why":"*Praktikant* to słaby rzeczownik, więc dostaje *-en*, a nie *-s*."},{"type":"fill","q":"___ (wegen / der Regen) bleiben wir heute zu Hause.","a":["Wegen des Regens"],"why":"*wegen* + dopełniacz w piśmie. *der Regen* jest rodzaju męskiego: *des Regens*. W mowie usłyszysz też *wegen dem Regen*."},{"type":"fill","q":"Ich lese den Bericht ___ (das Team).","a":["des Teams"],"why":"Rodzaj nijaki: *des* plus *-s*."},{"type":"rewrite","q":"die Meinung von meiner Chefin","a":["die Meinung meiner Chefin"],"why":"Zaimek dzierżawczy w rodzaju żeńskim: *meiner*."},{"type":"rewrite","q":"während dem Essen","a":["während des Essens"],"why":"*während* łączy się w piśmie z dopełniaczem. *das Essen* jest rodzaju nijakiego: *des Essens*."},{"type":"choose","q":"___ des Streiks fahren heute keine Busse. (Wegen / Weil)","a":["Wegen"],"why":"Dalej stoi rzeczownik w dopełniaczu (*des Streiks*), więc potrzebujesz przyimka *wegen*."},{"type":"choose","q":"Ich komme etwas später, ___ ich noch einen Termin habe. (wegen / weil)","a":["weil"],"why":"Dalej stoi zdanie z czasownikiem na końcu, więc potrzebujesz *weil*."},{"type":"choose","q":"___ es kalt ist, gehen wir im See schwimmen. (Trotz / Obwohl)","a":["Obwohl"],"why":"Dalej stoi zdanie z czasownikiem, więc potrzebujesz spójnika *obwohl*."},{"type":"choose","q":"___ der Kälte gehen wir im See schwimmen. (Trotz / Obwohl)","a":["Trotz"],"why":"Dalej stoi rzeczownik w dopełniaczu (*der Kälte*), więc potrzebujesz przyimka *trotz*."}]},"sources":[{"id":"kasus","title":"grammis: Kasus (przypadek)","url":"https://grammis.ids-mannheim.de/vggf/2218"},{"id":"s-es","title":"grammis: Eines Tags oder eines Tages? Krótkie i długie formy dopełniacza","url":"https://grammis.ids-mannheim.de/fragen/26"},{"id":"weak","title":"grammis: Autor, Doktor, Friede, Funke (rzeczowniki słabe i mieszane)","url":"https://grammis.ids-mannheim.de/fragen/28"},{"id":"prep","title":"grammis: Präpositionalphrase (przyimki i przypadki, których wymagają)","url":"https://grammis.ids-mannheim.de/kontrastive-grammatik/5747"},{"id":"wegen","title":"grammis: Wegen dem Regen oder wegen des Regens? Celownik czy dopełniacz","url":"https://grammis.ids-mannheim.de/fragen/67"}]},{"id":"konjunktiv-2","number":8,"added":"2026-11-06","level":"B1.1","title":"Konjunktiv","title_en":"Tryb przypuszczający: uprzejmość, życzenia i sytuacje nierealne","summary":"Mów uprzejmie (*Könnten Sie …?*), dawaj rady (*Du solltest …*), wyrażaj życzenia i mów o tym, co nierealne (*Wenn ich Zeit hätte, würde ich …*).","purpose":["Zwykłe formy czasownika (tryb oznajmujący) opisują to, co **jest** realne: *Ich habe Zeit.* (Mam czas.) Konjunktiv II opisuje to, co **nie** jest realne albo jeszcze nie jest realne: *Wenn ich Zeit **hätte**, …* (Gdybym miał czas, …).","Używasz go też codziennie, żeby brzmieć **uprzejmie** i **mniej bezpośrednio**: *Ich **hätte** gern einen Kaffee.* (Chciał(a)bym kawę.) *Könnten Sie mir helfen?* (Czy mógłby mi Pan / mogłaby mi Pani pomóc?) Odpowiada mniej więcej angielskim *would*, *could* i *should*, a po polsku formom z „-by”."],"logic":["Większość czasowników tworzy go za pomocą **würde + bezokolicznik**, według tego samego wzoru co przy czasowniku modalnym: *würde* na pozycji 2, bezokolicznik na końcu. *Ich **würde** gern in Bern **wohnen**.*","Kilka bardzo częstych czasowników ma **własną formę jednowyrazową**, utworzoną od formy czasu przeszłego Präteritum z przegłosem: *war → **wäre***, *hatte → **hätte***, *konnte → **könnte***. Używaj ich zamiast *würde … sein / haben*.","Końcówki są takie same dla wszystkich: *ich -e, du -est, er/sie/es -e, wir -en, ihr -et, sie/Sie -en*.","Dla **przeszłości** użyj *hätte* lub *wäre* plus Partizip II, jak w czasie Perfekt: *Ich **hätte** dich **angerufen**.* (Zadzwoniłbym do ciebie.)"],"rules":[{"title":"Formy jednowyrazowe: wäre, hätte, würde, könnte","text":"Weź formę Präteritum (*war, hatte, wurde, konnte*), dodaj przegłos i użyj końcówek z *-e*.","table":{"caption":"Konjunktiv II czterech kluczowych czasowników","head":["","sein","haben","werden","können"],"rows":[["ich","**wäre**","**hätte**","**würde**","**könnte**"],["du","wär(e)st","hättest","würdest","könntest"],["er / sie / es","wäre","hätte","würde","könnte"],["wir","wären","hätten","würden","könnten"],["ihr","wär(e)t","hättet","würdet","könntet"],["sie / Sie","wären","hätten","würden","könnten"]]},"examples":[{"de":"Ich **wäre** jetzt gern in den Bergen.","en":"Chętnie byłbym teraz w górach."},{"de":"Wir **hätten** gern mehr Ferien.","en":"Chcielibyśmy mieć więcej urlopu."}],"source":"k2"},{"title":"würde + bezokolicznik dla większości pozostałych czasowników","text":"*würde* stoi na pozycji 2, a bezokolicznik idzie na koniec – to ta sama klamra czasownikowa co przy *können* czy *müssen*.","examples":[{"de":"Ich **würde** gern mehr **reisen**.","en":"Chętnie podróżowałbym więcej."},{"de":"An deiner Stelle **würde** ich mit der Chefin **sprechen**.","en":"Na twoim miejscu porozmawiałbym z szefową."}],"source":"flexion"},{"title":"Czasowniki modalne: könnte, müsste, dürfte, möchte","text":"Czasowniki modalne dostają w Konjunktiv II przegłos: *könnte* (mógłby), *müsste* (musiałby), *dürfte* (mógłby, wolno by mu było), *möchte* (chciałby). **Wyjątki:** *sollte* (powinien) i *wollte* (chciałby): nie mają przegłosu, więc wyglądają tak samo jak Präteritum.","examples":[{"de":"**Dürfte** ich kurz stören?","en":"Czy mógłbym na chwilę przeszkodzić?"},{"de":"Du **solltest** mehr Pausen machen.","en":"Powinieneś robić więcej przerw."},{"de":"Eigentlich **müsste** ich heute noch einkaufen.","en":"Właściwie musiałbym dziś jeszcze zrobić zakupy."}],"source":"modal"},{"title":"Cztery zastosowania: uprzejmość, rada, życzenia, warunki nierealne","text":["**Uprzejme prośby:** *Könnten Sie …? Würden Sie …? Hätten Sie …? Ich hätte gern …*","**Rady:** *Du solltest … An deiner Stelle würde ich …*","**Życzenia:** *Ich wäre gern … Ich hätte gern … Wenn ich doch mehr Zeit hätte!*","**Warunki nierealne:** *Wenn ich mehr Geld hätte, würde ich weniger arbeiten.*"],"examples":[{"de":"**Könnten** Sie mir bitte die Rechnung schicken?","en":"Czy mógłby mi Pan / mogłaby mi Pani przesłać fakturę?"},{"de":"**Würden** Sie das bitte noch einmal erklären?","en":"Czy wyjaśniłby Pan / wyjaśniłaby Pani to jeszcze raz?"},{"de":"Wenn ich doch mehr Zeit **hätte**!","en":"Gdybym tylko miał więcej czasu!"}],"source":"k2"},{"title":"Zdania z wenn: czasownik na końcu, potem czasownik na początku","text":"W zdaniu z *wenn* odmieniony czasownik idzie na **koniec**. Jeśli zdanie z *wenn* stoi na początku, zdanie główne **zaczyna się od czasownika**: *Wenn ich Zeit hätte, **würde** ich kommen.*","examples":[{"de":"Wenn ich mehr Zeit **hätte**, **würde** ich einen Abendkurs **besuchen**.","en":"Gdybym miał więcej czasu, chodziłbym na kurs wieczorowy."},{"de":"Ich **würde** mitkommen, wenn ich nicht arbeiten **müsste**.","en":"Poszedłbym z wami, gdybym nie musiał pracować."}],"source":"flexion"},{"title":"Przeszłość: hätte / wäre + Partizip II","text":"Gdy mówisz o czymś w przeszłości, co się nie wydarzyło, użyj *hätte* lub *wäre* plus Partizip II. Wybór między *hätte* a *wäre* jest taki sam jak w czasie Perfekt (*haben* czy *sein*).","examples":[{"de":"Wenn der Zug pünktlich **gewesen wäre**, **hätte** ich das Meeting nicht **verpasst**.","en":"Gdyby pociąg przyjechał punktualnie, nie przegapiłbym spotkania."},{"de":"Das **hätte** ich nicht **gedacht**.","en":"Tego bym nie pomyślał."}],"source":"k2"}],"exceptions":[{"title":"Czasowniki regularne zawsze z würde","text":"W czasownikach regularnych (słabych) jednowyrazowy Konjunktiv II wygląda dokładnie jak Präteritum: *ich arbeitete* może znaczyć „pracowałem” albo „pracowałbym”. Żeby było jasne, użyj **würde**: *Wenn ich weniger arbeiten **würde**, …*","examples":[{"de":"Wenn er mehr **lernen würde**, **hätte** er bessere Noten.","en":"Gdyby więcej się uczył, miałby lepsze oceny."}],"source":"synkretismus"},{"title":"Niektóre formy jednowyrazowe, które przeczytasz i usłyszysz","text":"Czasowniki mocne też mają formy jednowyrazowe. Większość brzmi oficjalnie (*käme, ginge*), ale kilka jest częstych także w mowie: *es **gäbe*** (byłoby, istniałoby), *ich **wüsste*** (wiedziałbym), *ich **bräuchte*** (potrzebowałbym).","examples":[{"de":"**Wüssten** Sie, wo das Sitzungszimmer ist?","en":"Czy wiedziałby Pan / wiedziałaby Pani, gdzie jest sala zebrań?"},{"de":"Es **wäre** gut, wenn es mehr Parkplätze **gäbe**.","en":"Byłoby dobrze, gdyby było więcej miejsc parkingowych."}],"source":"flexion"}],"mistakes":[{"wrong":"Ich würde gern einen Kaffee haben.","right":"Ich **hätte** gern einen Kaffee.","why":"Przy *haben* i *sein* używaj *hätte* i *wäre*, a nie *würde … haben / sein*. Wersja z *würde* nie jest błędna, ale brzmi niezgrabnie."},{"wrong":"Wenn ich Zeit hätte, ich würde kommen.","right":"Wenn ich Zeit hätte, **würde ich** kommen.","why":"Po zdaniu z *wenn* zdanie główne zaczyna się od czasownika."},{"wrong":"Wenn ich würde Zeit haben, …","right":"Wenn ich Zeit **hätte**, …","why":"W zdaniu z *wenn* czasownik idzie na koniec, a *haben* ma formę *hätte*."},{"wrong":"Ich könnte gestern nicht kommen.","right":"Ich **konnte** gestern nicht kommen.","why":"*konnte* (bez przegłosu) = mogłem, byłem w stanie. *könnte* = mógłbym, byłbym w stanie. Przegłos zmienia znaczenie."},{"wrong":"Wenn ich das gewusst würde, …","right":"Wenn ich das gewusst **hätte**, …","why":"Dla przeszłości użyj *hätte* lub *wäre* plus Partizip II."},{"wrong":"Wenn ich mehr Geld habe, würde ich weniger arbeiten.","right":"Wenn ich mehr Geld **hätte**, würde ich weniger arbeiten.","why":"Jeśli sytuacja jest nierealna, obie części są nierealne. Angielski (*if I had*), francuski (*si j'avais*), włoski (*se avessi*) i hiszpański (*si tuviera*) też zmieniają czasownik w części z „if”."},{"wrong":"Ich hätte gestern gekommen.","right":"Ich **wäre** gestern gekommen.","why":"W przeszłości *hätte* lub *wäre* wybiera się jak w czasie Perfekt: *ich bin gekommen* → *ich wäre gekommen*. Angielski używa *have* przy każdym czasowniku (*I would have come*), niemiecki nie."},{"wrong":"Du söllst mehr schlafen.","right":"Du **solltest** mehr schlafen.","why":"*sollen* i *wollen* nie dostają przegłosu w trybie przypuszczającym (Konjunktiv II): *sollte*, *wollte*."}],"examples":[{"de":"Ich **hätte** gern einen Termin am Dienstag.","en":"Chciałbym umówić termin na wtorek."},{"de":"**Könntest** du mir kurz helfen?","en":"Mógłbyś mi na chwilę pomóc?"},{"de":"Es **wäre** schön, wenn wir uns bald **sehen würden**.","en":"Byłoby miło, gdybyśmy wkrótce się zobaczyli."},{"de":"An deiner Stelle **würde** ich das Angebot **annehmen**.","en":"Na twoim miejscu przyjąłbym tę ofertę."},{"de":"Ich **wäre** lieber Lehrerin geworden.","en":"Wolałabym była zostać nauczycielką."},{"de":"Wenn ich in Zürich **wohnen würde**, **müsste** ich nicht so lange pendeln.","en":"Gdybym mieszkał w Zurychu, nie musiałbym tak daleko dojeżdżać."},{"de":"**Hätten** Sie morgen Zeit für ein kurzes Gespräch?","en":"Czy miałby Pan / miałaby Pani jutro czas na krótką rozmowę?"},{"de":"Wir **sollten** früher losfahren.","en":"Powinniśmy wyjechać wcześniej."}],"later":"**Konjunktiv I** (*er sei, sie habe*) służy do mowy zależnej, głównie w wiadomościach i tekstach oficjalnych. Wystarczy, że nauczysz się go rozpoznawać później, na poziomie B2.","selfcheck":{"types":{"fill":{"label":"Uzupełnij lukę","instruction":"Wstaw czasownik z nawiasu w Konjunktiv II. Napisz jedno słowo.","example":{"q":"Ich ___ gern Urlaub. (haben)","a":"hätte","why":"*haben* → *hätte*, jedno słowo, bez *würde*."}},"polite":{"label":"Powiedz to uprzejmie","instruction":"Zamień bezpośrednie polecenie na uprzejme pytanie z *Könnten Sie* lub *Würden Sie*. Napisz całe zdanie. *bitte* możesz dodać, ale nie musisz.","example":{"q":"Schicken Sie mir den Plan.","a":"Könnten Sie mir bitte den Plan schicken?","why":"*Könnten* stoi na początku, a bezokolicznik idzie na koniec."}},"real":{"label":"Realne czy nierealne?","instruction":"Wybierz z nawiasu pasujący czasownik i napisz tylko to słowo. Rzeczy realne lub możliwe mają zwykłą formę (*habe, konnte*); rzeczy nierealne, uprzejme lub wymarzone mają Konjunktiv II (*hätte, könnte*).","example":{"q":"Wenn es morgen regnet, ___ wir zu Hause. (bleiben / blieben)","a":"bleiben","why":"Deszcz jutro jest możliwy, więc obie części mają zwykły czas teraźniejszy."}}},"items":[{"type":"fill","q":"Wenn ich du ___, würde ich das Angebot annehmen. (sein)","a":["wäre"],"why":"*sein* → *wäre*. W zdaniu z *wenn* czasownik idzie na koniec."},{"type":"fill","q":"___ Sie mir bitte helfen? (können)","a":["Könnten"],"why":"Uprzejme pytanie: *Könnten Sie …?*"},{"type":"fill","q":"Du ___ zum Arzt gehen. (sollen)","a":["solltest"],"why":"Rada z *sollen*: *du solltest*, bez przegłosu."},{"type":"fill","q":"Wir ___ gern ein grösseres Büro. (haben)","a":["hätten"],"why":"*wir hätten*, z końcówką *-en* dla *wir*."},{"type":"fill","q":"Wenn ich früher aufgestanden ___, hätte ich den Bus erreicht. (sein)","a":["wäre"],"why":"Przeszłość: *aufstehen* tworzy Perfekt z *sein*, więc *wäre aufgestanden*."},{"type":"polite","q":"Geben Sie mir das Formular.","a":["Könnten Sie mir das Formular geben?","Könnten Sie mir bitte das Formular geben?","Könnten Sie mir das Formular bitte geben?","Würden Sie mir das Formular geben?","Würden Sie mir bitte das Formular geben?","Würden Sie mir das Formular bitte geben?"],"why":"Najpierw *Könnten Sie* lub *Würden Sie*, a *geben* na końcu."},{"type":"real","q":"Wenn ich morgen Zeit ___, komme ich vorbei. (habe / hätte)","a":["habe"],"why":"Realna możliwość: zdanie główne ma zwykłą formę (*komme*), więc zdanie z *wenn* też."},{"type":"real","q":"Wenn ich mehr Zeit ___, würde ich öfter Sport machen. (habe / hätte)","a":["hätte"],"why":"Sytuacja nierealna: zdanie główne ma *würde*, więc zdanie z *wenn* potrzebuje *hätte*."},{"type":"real","q":"Gestern ___ ich nicht kommen, weil ich krank war. (konnte / könnte)","a":["konnte"],"why":"Realny fakt z przeszłości: Präteritum *konnte*, bez przegłosu."},{"type":"real","q":"___ Sie mir bitte das Salz geben? (Konnten / Könnten)","a":["Könnten"],"why":"Uprzejma prośba: Konjunktiv II *Könnten*, z przegłosem."}]},"sources":[{"id":"k2","title":"grammis: Konjunktiv II","url":"https://grammis.ids-mannheim.de/terminologie/401"},{"id":"flexion","title":"grammis: Verbflexion nach Tempus und Modus (formy czasownika według czasu i trybu)","url":"https://grammis.ids-mannheim.de/progr@mm/4047"},{"id":"modal","title":"grammis: Modalverb (czasowniki modalne)","url":"https://grammis.ids-mannheim.de/progr@mm/5202"},{"id":"synkretismus","title":"grammis: Formensynkretismus von Konjunktiv und Indikativ (gdy tryb przypuszczający i oznajmujący wyglądają tak samo)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/315"}]},{"id":"wegen-weil-deshalb-dann","number":9,"added":"2026-11-09","level":"B1.1","title":"wegen / weil / deshalb / deswegen / darum / dann","title_en":"Przyczyna czy skutek? Które słowa można zamieniać i dlaczego dann jest inne","summary":"Mów, dlaczego, za pomocą *wegen* (+ rzeczownik), *weil* (czasownik na końcu) lub *denn*; mów, co z tego wynika, za pomocą *deshalb, deswegen, darum*; a *dann* zostaw dla „potem”.","purpose":["Podawanie przyczyn to jedna z rzeczy, które robisz po niemiecku najczęściej: gdy się usprawiedliwiasz, wyjaśniasz decyzję, argumentujesz w liście lub dyskusji na B1. Niemiecki ma na to kilka słów. Różnią się mniej **znaczeniem**, a bardziej **gramatyką**: tym, co po nich stoi, i tym, gdzie idzie czasownik.","Ten temat opiera się na Temacie 5 (*weil, denn, deshalb*) i Temacie 7 (*wegen* + dopełniacz). Pokazuje jedną sytuację na wszystkie sposoby, wyjaśnia, które słowa można zamieniać, i tłumaczy, dlaczego *dann* do nich nie należy, choć wygląda i brzmi podobnie."],"logic":["O wyborze słowa decydują dwa pytania. **1. Kierunek:** czy słowo wprowadza **przyczynę** (*dlaczego?*), czy **skutek** (*i co z tego wynika?*)? **2. Co stoi dalej:** rzeczownik, zdanie z czasownikiem na końcu czy zwykłe zdanie?","**Przyczyna:** **wegen** + rzeczownik (*wegen des Regens*), **weil** + zdanie z czasownikiem na końcu (*weil es regnet*), **denn** + zwykłe zdanie (*denn es regnet*).","**Skutek:** **deshalb**, **deswegen** i **darum** znaczą *dlatego, więc*. Wskazują wstecz na przyczynę: *deswegen* to dosłownie *des* + *wegen*, „z tego powodu”. Na pozycji 1 zaraz po nich stoi czasownik.","**dann** nie należy do żadnej strony. Znaczy *potem / wtedy*: to, co następuje **później w czasie** (*zuerst … dann*), albo to, co wynika, **jeśli** warunek jest spełniony (*wenn … dann*). Nigdy nie mówi *dlaczego*.","Szybki test: jeśli poprzednie zdanie odpowiada na ***Warum?***, użyj *deshalb*. Jeśli odpowiada na ***Wann?*** lub ***Unter welcher Bedingung?***, użyj *dann*."],"rules":[{"title":"Jedna sytuacja na wszystkie sposoby","text":["Weź jedną przyczynę i jeden skutek: *Der Zug hat Verspätung* (przyczyna) → *ich komme zu spät* (skutek). Każde słowo łączy je inaczej.","*dann* pasuje tylko wtedy, gdy zamienisz przyczynę w **warunek** (*wenn …*): wtedy to możliwość, a nie fakt."],"table":{"caption":"Der Zug hat Verspätung → ich komme zu spät","head":["słowo","co stoi dalej","przykład"],"rows":[["**wegen**","rzeczownik (przyimek; dopełniacz, w mowie często celownik)","**Wegen der Verspätung** komme ich zu spät."],["**weil**","zdanie, czasownik na końcu (spójnik)","Ich komme zu spät, **weil** der Zug Verspätung **hat**."],["**denn**","zwykłe zdanie, czasownik na pozycji 2 (spójnik)","Ich komme zu spät, **denn** der Zug **hat** Verspätung."],["**deshalb**, **deswegen**, **darum**","czasownik, zaraz po nim (przysłówek)","Der Zug hat Verspätung, **deshalb komme** ich zu spät."],["**dann**","czasownik, zaraz po nim (przysłówek czasu lub warunku)","**Wenn** der Zug Verspätung hat, **dann komme** ich zu spät."]]},"examples":[{"de":"**Wegen der Verspätung** komme ich zu spät.","en":"Z powodu opóźnienia się spóźnię."},{"de":"Ich komme zu spät, **weil** der Zug Verspätung **hat**.","en":"Spóźnię się, ponieważ pociąg ma opóźnienie."},{"de":"Ich komme zu spät, **denn** der Zug **hat** Verspätung.","en":"Spóźnię się, bo pociąg ma opóźnienie."},{"de":"Der Zug hat Verspätung, **deshalb komme** ich zu spät.","en":"Pociąg ma opóźnienie, dlatego się spóźnię."},{"de":"**Wenn** der Zug Verspätung hat, **dann komme** ich zu spät.","en":"Jeśli pociąg będzie miał opóźnienie, to się spóźnię.","note":"Tutaj opóźnienie jest tylko możliwością. *dann* podaje skutek warunku, a nie przyczynę."}],"source":"ursache"},{"title":"Które słowa można zamieniać?","text":["**deshalb**, **deswegen** i **darum** można swobodnie zamieniać: to samo znaczenie, to samo miejsce, ten sam szyk. Wszystkie trzy to standardowy niemiecki. W tekstach pisanych *deshalb* jest zdecydowanie najczęstsze: w korpusie IDS niemieckich gazet i książek (DeReKo) występuje około pięciu razy częściej niż *deswegen*.","**weil**, **denn** i **wegen** podają przyczynę, ale gramatyka po nich się zmienia. **weil/denn** i **deshalb** opisują to samo powiązanie z przeciwnych stron: zamień obie połowy miejscami. **dann** nie zamienia się z żadnym z nich."],"table":{"caption":"Zamieniać czy nie?","head":["zamiana","to samo znaczenie?","co się zmienia"],"rows":[["**deshalb** ↔ **deswegen** ↔ **darum**","tak","nic"],["**weil** ↔ **denn**","tak","czasownik: na końcu po *weil*, na pozycji 2 po *denn*. Tylko *weil* może stać na początku albo odpowiedzieć na *Warum?*"],["**weil** ↔ **wegen**","tak","*wegen* łączy się z rzeczownikiem zamiast ze zdaniem: *weil es regnet* → *wegen des Regens*"],["**weil** / **denn** ↔ **deshalb**","tak, z drugiej strony","obie połowy zamieniają się miejscami: najpierw przyczyna, potem *deshalb* + skutek"],["**dann** ↔ dowolne z nich","nie","*dann* znaczy *potem / wtedy*: kolejność w czasie albo skutek warunku z *wenn*"]]},"examples":[{"de":"Es regnet. **Deshalb** bleiben wir zu Hause.","en":"Pada deszcz. Dlatego zostajemy w domu."},{"de":"Es regnet. **Darum** bleiben wir zu Hause.","en":"Pada deszcz. Z tego powodu zostajemy w domu.","note":"To samo zdanie co z *deshalb*: nic więcej się nie zmienia."},{"de":"Wir bleiben zu Hause, **weil** es **regnet**.","en":"Zostajemy w domu, ponieważ pada deszcz."},{"de":"**Wegen des Regens** bleiben wir zu Hause.","en":"Z powodu deszczu zostajemy w domu."}],"source":"deshalb"},{"title":"wegen + rzeczownik: przyczyna w jednej frazie","text":["**wegen** (z powodu) to przyimek: potrzebuje **rzeczownika**, a nie zdania. W piśmie łączy się z **dopełniaczem** (*wegen **des** Streiks, wegen **der** Baustelle*). O celowniku w mowie przeczytasz niżej w wyjątkach i w Temacie 7.","Żeby zamienić zdanie z *weil* na frazę z *wegen*, znajdź w nim rzeczownik: *weil es regnet* → *wegen des **Regens***, *weil ich erkältet bin* → *wegen meiner **Erkältung***."],"examples":[{"de":"**Wegen des Streiks** fahren heute keine Busse.","en":"Z powodu strajku dziś nie jeżdżą autobusy."},{"de":"Das Konzert findet **wegen des Regens** in der Halle statt.","en":"Z powodu deszczu koncert odbędzie się w hali."},{"de":"**Wegen einer Baustelle** ist die Strasse bis Freitag gesperrt.","en":"Z powodu robót drogowych ulica jest zamknięta do piątku."},{"de":"**Wegen meiner Erkältung** kann ich heute nicht ins Training.","en":"Z powodu przeziębienia nie mogę dziś iść na trening."},{"de":"Ich rufe **wegen der Wohnung** an.","en":"Dzwonię w sprawie mieszkania.","note":"Gdy mówisz, dlaczego dzwonisz lub piszesz, po angielsku mówi się *about*, a po polsku „w sprawie”; po niemiecku nadal *wegen*."}],"source":"wegen"},{"title":"weil: czasownik na końcu i odpowiedź na Warum?","text":["**weil** rozpoczyna zdanie podrzędne: odmieniony czasownik idzie na **koniec**. Jeśli zdanie z *weil* stoi na początku, zdanie główne zaczyna się od swojego czasownika.","**weil** to jedyne z tych słów, które samo może odpowiedzieć na pytanie ***Warum?***: *Warum? – Weil …*."],"examples":[{"de":"Ich komme heute später, **weil** mein Zug Verspätung **hat**.","en":"Przyjdę dziś później, ponieważ mój pociąg ma opóźnienie."},{"de":"**Weil** die Miete so hoch **ist**, **suchen** wir eine neue Wohnung.","en":"Ponieważ czynsz jest tak wysoki, szukamy nowego mieszkania."},{"de":"Warum lernst du Deutsch? – **Weil** ich in Zürich **arbeite**.","en":"Dlaczego uczysz się niemieckiego? – Bo pracuję w Zurychu."},{"de":"Sie hat die Stelle bekommen, **weil** sie gut Französisch **spricht**.","en":"Dostała tę pracę, ponieważ dobrze mówi po francusku."},{"de":"Ich kann nicht mitkommen, **weil** ich heute Abend arbeiten **muss**.","en":"Nie mogę pójść z wami, ponieważ dziś wieczorem muszę pracować.","note":"Przy dwóch czasownikach ten odmieniony (*muss*) idzie na sam koniec."}],"source":"kausal"},{"title":"denn: to samo znaczenie co weil, zwykły szyk","text":["**denn** (bo) też podaje przyczynę, ale nie przesuwa czasownika: stoi na **pozycji 0**, więc czasownik zostaje na **pozycji 2**.","Część z *denn* zawsze stoi **po** zdaniu, które wyjaśnia. Może zaczynać nowe zdanie (*… . Denn …*), ale nie może stać na początku i nie może sama odpowiedzieć na *Warum?*: do tego użyj *weil*."],"examples":[{"de":"Ich nehme den Zug, **denn** die Autobahn **ist** um diese Zeit immer voll.","en":"Jeżdżę pociągiem, bo autostrada o tej porze jest zawsze zapchana."},{"de":"Nimm einen Schirm mit, **denn** am Nachmittag **soll** es regnen.","en":"Weź parasol, bo po południu ma padać."},{"de":"Wir essen heute zu Hause. **Denn** das Restaurant **ist** am Montag geschlossen.","en":"Dziś jemy w domu. Bo restauracja w poniedziałek jest zamknięta.","note":"Nowe zdanie z *denn* jest w porządku, pod warunkiem że stoi po zdaniu, które wyjaśnia."}],"source":"denn"},{"title":"deshalb: bezpieczny wybór dla skutku","text":["**deshalb** (dlatego, więc) wprowadza **skutek** i wskazuje wstecz na przyczynę, która stoi przed nim. To przysłówek: na pozycji 1 **czasownik stoi zaraz po nim** albo sam stoi w środku zdania, po czasowniku.","W piśmie to najczęstsze z tych trzech słów, więc w razie wątpliwości użyj *deshalb*."],"examples":[{"de":"Mein Zug hatte Verspätung. **Deshalb bin** ich zu spät gekommen.","en":"Mój pociąg miał opóźnienie. Dlatego się spóźniłem."},{"de":"Die Kita schliesst um sechs. Ich **muss deshalb** pünktlich gehen.","en":"Żłobek zamyka się o szóstej. Muszę więc wyjść punktualnie."},{"de":"Ich möchte in der Pflege arbeiten. **Deshalb mache** ich eine Ausbildung.","en":"Chciałabym pracować w opiece nad chorymi. Dlatego robię szkolenie zawodowe."},{"de":"Am Samstag ist der Coop sehr voll, **deshalb kaufe** ich am Freitag ein.","en":"W sobotę w Coopie jest bardzo tłoczno, dlatego robię zakupy w piątek."},{"de":"Der Lift ist kaputt. Wir **nehmen deshalb** die Treppe.","en":"Winda jest zepsuta. Idziemy więc schodami."}],"source":"deshalb"},{"title":"deswegen: „z tego powodu”","text":"**deswegen** znaczy dokładnie to samo co *deshalb* i działa tak samo: na pozycji 1 czasownik stoi zaraz po nim albo ono samo stoi w środku zdania. Jego części pokazują znaczenie: *des* + *wegen*, „z tego powodu”. To standardowy niemiecki, w mowie i w piśmie.","examples":[{"de":"Ich habe schlecht geschlafen. **Deswegen bin** ich heute so müde.","en":"Źle spałem. Dlatego jestem dziś taki zmęczony."},{"de":"Es hat die ganze Nacht geschneit, **deswegen fahren** die Trams langsam.","en":"Całą noc padał śnieg, dlatego tramwaje jeżdżą powoli."},{"de":"Meine Kollegin ist krank. Ich **übernehme deswegen** ihre Kunden.","en":"Moja koleżanka z pracy jest chora. Dlatego przejmuję jej klientów."},{"de":"Die Wohnung liegt direkt am Bahnhof. **Deswegen ist** sie so teuer.","en":"Mieszkanie jest tuż przy dworcu. Dlatego jest takie drogie."},{"de":"Sie spricht vier Sprachen. **Deswegen arbeitet** sie am Empfang.","en":"Ona zna cztery języki. Dlatego pracuje w recepcji."}],"source":"deswegen"},{"title":"darum: to samo znaczenie, ale też inne zastosowania","text":["**darum** też znaczy *dlatego, więc*, z takim samym szykiem jak *deshalb*.","Uważaj: *darum* ma też inne znaczenia, które nie mają nic wspólnego z przyczynami, na przykład *Es geht darum* (chodzi o to) albo *sich darum kümmern* (zająć się tym). Zobacz wyjątki poniżej."],"examples":[{"de":"Im Zug kann ich lesen. **Darum fahre** ich lieber Zug als Auto.","en":"W pociągu mogę czytać. Dlatego wolę jeździć pociągiem niż samochodem."},{"de":"Ich mag meinen Job. **Darum bleibe** ich in der Firma.","en":"Lubię swoją pracę. Dlatego zostaję w firmie."},{"de":"Es war schon spät, **darum haben** wir ein Taxi genommen.","en":"Było już późno, więc wzięliśmy taksówkę."},{"de":"Mit dem Velo bin ich in der Stadt am schnellsten. Ich **fahre darum** jeden Tag mit dem Velo zur Arbeit.","en":"W mieście najszybciej poruszam się rowerem. Dlatego codziennie jeżdżę rowerem do pracy."},{"de":"Der Kurs war sehr gut. **Darum empfehle** ich ihn weiter.","en":"Kurs był bardzo dobry. Dlatego go polecam."}],"source":"darum"},{"title":"deshalb …, weil: wskazanie na przyczynę","text":"Możesz użyć *deshalb* (lub *deswegen*, *darum*) i *weil* w jednym zdaniu. *deshalb* wskazuje wtedy naprzód na zdanie z *weil* i podkreśla: **to** jest przyczyna, a nie inna. Często występuje z *nur* lub *gerade* (tylko, właśnie).","examples":[{"de":"Ich bin **deshalb** nach Bern gezogen, **weil** meine Partnerin hier arbeitet.","en":"Przeprowadziłem się do Berna właśnie dlatego, że moja partnerka tu pracuje."},{"de":"Er hat die Stelle nur **deswegen** bekommen, **weil** er Italienisch spricht.","en":"Dostał tę pracę tylko dlatego, że mówi po włosku."},{"de":"**Weil** mir kalt ist, **deshalb** ziehe ich die Winterjacke an.","en":"Ponieważ jest mi zimno, to zakładam zimową kurtkę.","note":"Po zdaniu z *weil* słowo *deshalb* powtarza przyczynę. Możesz je pominąć: *Weil mir kalt ist, ziehe ich …*"}],"source":"korrelat"},{"title":"dann: potem, a nie dlatego","text":["**dann** to przysłówek **czasu**: mówi, co następuje **potem** (*zuerst … dann*) albo w późniejszym momencie. Po zdaniu z **wenn** podaje, co się dzieje, **jeśli** warunek jest spełniony (*wenn … dann*). W odpowiedzi znaczy *w takim razie*.","Szyk jest taki jak przy *deshalb*: na pozycji 1 czasownik stoi zaraz po nim. Ale znaczenie jest inne: *dann* nigdy nie wyjaśnia, **dlaczego**."],"examples":[{"de":"Zuerst gehe ich zur Post, **dann gehe** ich einkaufen.","en":"Najpierw idę na pocztę, potem idę na zakupy."},{"de":"Wir essen um sieben. **Dann schauen** wir einen Film.","en":"Jemy o siódmej. Potem oglądamy film."},{"de":"**Wenn** es morgen regnet, **dann bleiben** wir zu Hause.","en":"Jeśli jutro będzie padać, to zostaniemy w domu."},{"de":"**Wenn** Sie Fragen haben, **dann rufen** Sie mich an.","en":"Jeśli ma Pan / Pani pytania, to proszę do mnie zadzwonić."},{"de":"– Der letzte Bus ist schon weg. – **Dann nehmen** wir ein Taxi.","en":"– Ostatni autobus już odjechał. – W takim razie weźmiemy taksówkę.","note":"Reakcja na wiadomość: *dann* = „w takim razie”. Przedstawia decyzję, a nie wyjaśnienie."}],"source":"dann"},{"title":"dann, denn czy deshalb?","text":"*dann* i *denn* różnią się jedną literą, a angielskie *then* i *so* zacierają różnicę między *dann* a *deshalb*. Sprawdź znaczenie: **denn** = *bo* (dalej przyczyna), **deshalb** = *dlatego* (dalej skutek), **dann** = *potem / wtedy* (to, co następuje, lub to, co wynika z *wenn*).","table":{"caption":"Trzy podobne słowa","head":["słowo","znaczenie","co stoi po nim","przykład"],"rows":[["**denn**","bo (przyczyna)","zwykłe zdanie, czasownik na pozycji 2","Ich bleibe zu Hause, **denn ich bin** krank."],["**deshalb**","dlatego (skutek)","czasownik zaraz po nim","Ich bin krank, **deshalb bleibe** ich zu Hause."],["**dann**","potem, wtedy (czas, warunek)","czasownik zaraz po nim","Ich gehe zum Arzt, **dann gehe** ich nach Hause."]]},"examples":[{"de":"Ich bleibe zu Hause, **denn** ich bin krank.","en":"Zostaję w domu, bo jestem chory."},{"de":"Ich bin krank, **deshalb** bleibe ich zu Hause.","en":"Jestem chory, dlatego zostaję w domu."},{"de":"Ich gehe zum Arzt, **dann** gehe ich nach Hause.","en":"Idę do lekarza, potem idę do domu."},{"de":"**Wenn** ich krank bin, **dann** bleibe ich zu Hause.","en":"Jeśli jestem chory, to zostaję w domu."}],"source":"dann"}],"exceptions":[{"title":"wegen + celownik w mowie","text":"W mowie wiele osób mówi *wegen **dem** Regen* zamiast *wegen **des** Regens*, także w Szwajcarii. W mowie prawie nie uważa się tego za błąd, ale w piśmie dopełniacz to bezpieczny wybór. Z zaimkami normalny jest celownik: *wegen mir*. Więcej w Temacie 7.","examples":[{"de":"Wegen **dem** Stau bin ich zu spät gekommen. (gesprochen)","en":"Z powodu korka się spóźniłem."},{"de":"Wegen **des Staus** bin ich zu spät gekommen. (geschrieben)","en":"Z powodu korka się spóźniłem."}],"source":"wegen"},{"title":"Darum! jako odpowiedź","text":"*Darum!* samo w sobie, jako odpowiedź na *Warum?*, jest potoczne i szorstkie: odmawia podania przyczyny, jak polskie „Bo tak!”. Jeśli chcesz podać prawdziwy powód, odpowiedz z *weil*.","examples":[{"de":"– Warum muss ich das machen? – Darum!","en":"– Dlaczego muszę to zrobić? – Bo tak!"},{"de":"– Warum kommst du nicht mit? – **Weil** ich keine Zeit **habe**.","en":"– Dlaczego nie idziesz z nami? – Bo nie mam czasu."}],"source":"duden-darum"},{"title":"denn w pytaniu: w ogóle nie oznacza przyczyny","text":"W **pytaniu** *denn* jest partykułą, a nie słowem podającym przyczynę. Wyraża zainteresowanie lub zdziwienie, a w tłumaczeniu zwykle się je pomija. Słowo *denn* znaczące *bo* występuje tylko w zdaniach oznajmujących.","examples":[{"de":"Wo bist du **denn**?","en":"Gdzie ty w ogóle jesteś?"},{"de":"Was ist **denn** los?","en":"Co się stało?"},{"de":"Wie heisst **denn** deine neue Chefin?","en":"A jak się nazywa twoja nowa szefowa?"}],"source":"partikel"},{"title":"darum bez przyczyny: es geht darum, sich darum kümmern","text":"*darum* to także *da(r)* + *um*: zastępuje *um* + rzecz przy czasownikach i wyrażeniach z *um*. Wtedy znaczy *o to, o tym* i nie podaje przyczyny.","examples":[{"de":"Es geht **darum**, eine Lösung zu finden.","en":"Chodzi o to, żeby znaleźć rozwiązanie."},{"de":"Kannst du dich **darum** kümmern?","en":"Możesz się tym zająć?","note":"*sich um etwas kümmern* → *sich darum kümmern*."}],"source":"darum"}],"mistakes":[{"wrong":"Ich komme zu spät, dann der Zug hat Verspätung.","right":"Ich komme zu spät, **denn** der Zug hat Verspätung.","why":"*dann* (potem) i *denn* (bo) wyglądają i brzmią podobnie. Gdy podajesz przyczynę, pisz *denn*, przez *e*."},{"wrong":"Ich war krank. Dann bin ich nicht zur Arbeit gegangen.","right":"Ich war krank. **Deshalb** bin ich nicht zur Arbeit gegangen.","why":"*dann* mówi tylko, co było potem, a nie dlaczego. Włoskie *allora*, francuskie *alors* i hiszpańskie *entonces* mogą znaczyć zarówno „potem”, jak i „dlatego”, a angielskie *then* też może brzmieć jak skutek. Niemiecki je rozdziela: *dann* dla czasu, *deshalb* dla skutku."},{"wrong":"Deswegen ich komme zu spät.","right":"Deswegen **komme ich** zu spät.","why":"*deswegen*, *deshalb* i *darum* zajmują pozycję 1, więc zaraz po nich stoi czasownik. Angielskie *so I'm late*, francuskie *c'est pourquoi je …*, włoskie *per questo io …* i hiszpańskie *por eso yo …* stawiają najpierw podmiot; niemiecki nie."},{"wrong":"Wegen der Zug Verspätung hat, komme ich zu spät.","right":"**Weil** der Zug Verspätung hat, komme ich zu spät. / **Wegen der Verspätung** komme ich zu spät.","why":"*wegen* łączy się z rzeczownikiem, *weil* ze zdaniem. Ten sam podział istnieje w angielskim (*because of* / *because*), włoskim (*a causa di* / *perché*), francuskim (*à cause de* / *parce que*), hiszpańskim (*a causa de* / *porque*) i polskim (z powodu / ponieważ), ale uczący się często mylą tę niemiecką parę."},{"wrong":"Warum kommst du nicht? – Denn ich bin krank.","right":"Warum kommst du nicht? – **Weil** ich krank **bin**.","why":"Tylko *weil* może samo odpowiedzieć na *Warum?*. Część z *denn* zawsze potrzebuje zdania przed sobą."},{"wrong":"Ich bin müde, deshalb habe ich schlecht geschlafen.","right":"Ich habe schlecht geschlafen, **deshalb** bin ich müde.","why":"*deshalb* wprowadza **skutek**; przyczyna stoi przed nim. Złe spanie to przyczyna, zmęczenie – skutek. Jeśli chcesz zachować kolejność z błędnego zdania, użyj *weil*: *Ich bin müde, weil ich schlecht geschlafen habe.*"},{"wrong":"Wegen dem Streik fahren heute keine Busse. (in einem Brief)","right":"Wegen **des Streiks** fahren heute keine Busse.","why":"W mowie celownik po *wegen* jest częsty, ale w liście, e-mailu czy na egzaminie używaj dopełniacza."}],"examples":[{"de":"**Wegen der Hitze** arbeiten wir heute nur bis drei.","en":"Z powodu upału pracujemy dziś tylko do trzeciej."},{"de":"Ich rufe dich später an, **weil** ich gerade in einer Sitzung **bin**.","en":"Zadzwonię do ciebie później, ponieważ jestem teraz na zebraniu."},{"de":"Wir nehmen das Tram, **denn** in der Altstadt gibt es keine Parkplätze.","en":"Jedziemy tramwajem, bo na starym mieście nie ma miejsc parkingowych."},{"de":"Mein Velo hat einen Platten. **Deshalb** komme ich heute zu Fuss.","en":"Mam przebitą oponę w rowerze. Dlatego przychodzę dziś pieszo."},{"de":"Die Prüfung ist im Dezember. **Deswegen** lerne ich jeden Abend.","en":"Egzamin jest w grudniu. Dlatego uczę się co wieczór."},{"de":"Die Wohnung hat einen Balkon. **Darum** haben wir sie genommen.","en":"Mieszkanie ma balkon. Dlatego je wzięliśmy."},{"de":"Zuerst mache ich die Hausaufgaben, **dann** gehe ich ins Fitness.","en":"Najpierw odrobię lekcje, potem pójdę na siłownię."},{"de":"**Wenn** du Hilfe brauchst, **dann** sag es mir.","en":"Jeśli potrzebujesz pomocy, to mi powiedz."}],"later":"Więcej słów do podawania przyczyny pojawi się na poziomie B1.2 i B2: *da* (ponieważ, skoro: czasownik na końcu, głównie w piśmie, nie odpowiada na *Warum?*), *daher* (= *deshalb*, bardziej oficjalne), *nämlich* (podaje przyczynę, stoi po czasowniku: *Ich komme nicht, ich bin **nämlich** krank.*), *aus diesem Grund* (z tego powodu), *aufgrund* + dopełniacz (oficjalne *wegen*) i *sodass* (tak że).","selfcheck":{"types":{"choose":{"label":"Które słowo?","instruction":"Wpisz brakujące słowo: *wegen*, *weil*, *denn*, *deshalb* lub *dann*. Napisz tylko jedno słowo. Skorzystaj z dwóch wskazówek: znaczenia (przyczyna, skutek, kolejność w czasie lub warunek) i tego, co stoi po luce (rzeczownik, zdanie z czasownikiem na końcu, podmiot albo czasownik). Tam, gdzie pasuje *deshalb*, poprawne są też *deswegen* i *darum*.","example":{"q":"Ich trage eine Jacke, ___ es kalt ist.","a":"weil","why":"Przyczyna, a czasownik *ist* stoi na końcu → *weil*."}},"join":{"label":"Połącz zdania","instruction":"Połącz dwa zdania słowem z nawiasu. Zmień szyk tam, gdzie to słowo tego wymaga. Zdanie z *weil* może stać na początku albo na końcu; *deshalb, deswegen, darum* i *dann* mogą stać na pozycji 1 albo po czasowniku. Napisz całe nowe zdanie.","example":{"q":"Es ist schon spät. Ich nehme ein Taxi. (deshalb)","a":"Es ist schon spät, deshalb nehme ich ein Taxi.","why":"*deshalb* wprowadza skutek, a czasownik stoi zaraz po nim: *nehme ich*."}},"rewrite":{"label":"Powiedz to inaczej","instruction":"Powiedz to samo za pomocą słowa z nawiasu. Zachowaj znaczenie; zmień to, czego wymaga gramatyka: rzeczownik po *wegen*, czasownik na końcu po *weil*, zwykły szyk po *denn*, czasownik zaraz po *deshalb, deswegen, darum*. Przy *deshalb* i jego odpowiednikach przyczyna stoi na początku. Napisz całe nowe zdanie.","example":{"q":"Weil es schneit, fahren die Trams langsam. (wegen)","a":"Wegen des Schnees fahren die Trams langsam.","why":"*wegen* potrzebuje rzeczownika: *es schneit* → *der Schnee*, w dopełniaczu *des Schnees*."}}},"items":[{"type":"choose","q":"Ich komme heute später, ___ mein Zug Verspätung hat.","a":["weil"],"why":"Przyczyna, a czasownik (*hat*) stoi na końcu → *weil*."},{"type":"choose","q":"Ich komme heute später, ___ mein Zug hat Verspätung.","a":["denn"],"why":"Przyczyna, ale dalej stoi podmiot, a czasownik zostaje na pozycji 2 → *denn*."},{"type":"choose","q":"Ich habe die B1-Prüfung bestanden. ___ bin ich heute so glücklich.","a":["Deshalb","Deswegen","Darum"],"why":"Zdany egzamin to przyczyna, radość – skutek, a czasownik stoi zaraz po luce → *deshalb* (lub *deswegen*, *darum*)."},{"type":"choose","q":"Zuerst kaufe ich ein, ___ koche ich.","a":["dann"],"why":"*zuerst* (najpierw) wymaga tego, co następuje potem w czasie → *dann*. Zakupy nie są przyczyną gotowania."},{"type":"choose","q":"___ des Streiks fahren heute keine Busse.","a":["Wegen"],"why":"Dalej stoi rzeczownik w dopełniaczu (*des Streiks*), bez własnego czasownika → przyimek *wegen*."},{"type":"choose","q":"Wenn es morgen regnet, ___ bleiben wir zu Hause.","a":["dann"],"why":"Po warunku z *wenn* słowo *dann* podaje, co się stanie, jeśli warunek się spełni. *deshalb* potrzebuje jako przyczyny prawdziwego faktu, a nie „jeśli”."},{"type":"choose","q":"Warum lernst du Deutsch? – ___ ich in Zürich arbeite.","a":["Weil"],"why":"Samodzielna odpowiedź na *Warum?*, z czasownikiem (*arbeite*) na końcu → *weil*. *denn* nie może samo odpowiedzieć na pytanie."},{"type":"join","q":"Die Kita schliesst um 18 Uhr. Ich muss pünktlich gehen. (deswegen)","a":["Die Kita schliesst um 18 Uhr, deswegen muss ich pünktlich gehen.","Die Kita schliesst um 18 Uhr, ich muss deswegen pünktlich gehen.","Die Kita schliesst um 18 Uhr und deswegen muss ich pünktlich gehen.","Die Kita schliesst um 18 Uhr und ich muss deswegen pünktlich gehen."],"why":"*deswegen* wprowadza skutek; czasownik stoi zaraz po nim (*muss ich*) albo *deswegen* stoi po czasowniku."},{"type":"join","q":"Ich gehe zuerst einkaufen. Ich koche. (dann)","a":["Ich gehe zuerst einkaufen, dann koche ich.","Ich gehe zuerst einkaufen und dann koche ich."],"why":"Kolejność w czasie: *dann* na pozycji 1, czasownik zaraz po nim (*koche ich*)."},{"type":"join","q":"Ich trinke keinen Kaffee mehr. Ich schlafe schlecht. (weil)","a":["Ich trinke keinen Kaffee mehr, weil ich schlecht schlafe.","Weil ich schlecht schlafe, trinke ich keinen Kaffee mehr."],"why":"*weil* przesuwa czasownik (*schlafe*) na koniec. Jeśli zdanie z *weil* stoi na początku, zdanie główne zaczyna się od swojego czasownika (*trinke*)."},{"type":"rewrite","q":"Ich bleibe zu Hause, weil ich krank bin. (deshalb)","a":["Ich bin krank, deshalb bleibe ich zu Hause.","Ich bin krank, ich bleibe deshalb zu Hause.","Ich bin krank und deshalb bleibe ich zu Hause.","Ich bin krank und bleibe deshalb zu Hause.","Ich bin krank und ich bleibe deshalb zu Hause."],"why":"To samo powiązanie, widziane z drugiej strony: przyczyna (*ich bin krank*) stoi na początku, potem *deshalb* + czasownik + skutek."},{"type":"rewrite","q":"Wegen des Regens bleiben wir zu Hause. (weil)","a":["Weil es regnet, bleiben wir zu Hause.","Wir bleiben zu Hause, weil es regnet."],"why":"*weil* potrzebuje zdania: *der Regen* → *es regnet*, z czasownikiem na końcu."},{"type":"rewrite","q":"Ich nehme den Zug, weil die Autobahn voll ist. (denn)","a":["Ich nehme den Zug, denn die Autobahn ist voll."],"why":"*denn* zachowuje zwykły szyk: czasownik (*ist*) zostaje na pozycji 2, po podmiocie."},{"type":"rewrite","q":"Der Lift ist kaputt. Deshalb nehmen wir die Treppe. (darum)","a":["Der Lift ist kaputt. Darum nehmen wir die Treppe.","Der Lift ist kaputt, darum nehmen wir die Treppe.","Der Lift ist kaputt. Wir nehmen darum die Treppe.","Der Lift ist kaputt, wir nehmen darum die Treppe."],"why":"*deshalb* i *darum* można zamienić jeden na drugi: nic więcej się nie zmienia."},{"type":"rewrite","q":"Weil es einen Stau gab, bin ich zu spät gekommen. (wegen)","a":["Wegen des Staus bin ich zu spät gekommen.","Ich bin wegen des Staus zu spät gekommen.","Wegen eines Staus bin ich zu spät gekommen.","Ich bin wegen eines Staus zu spät gekommen.","Wegen dem Stau bin ich zu spät gekommen.","Ich bin wegen dem Stau zu spät gekommen."],"why":"*wegen* + rzeczownik: *einen Stau* → *des Staus* (dopełniacz, do pisania). *wegen dem Stau* jest w porządku w mowie."}]},"sources":[{"id":"ursache","title":"grammis: Ursache und Folge (weil oznacza przyczynę, deswegen skutek)","url":"https://grammis.ids-mannheim.de/progr@mm/6767"},{"id":"kausal","title":"grammis: Kausalsätze (weil odpowiada na pytania z warum; da nie)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/2102"},{"id":"wegen","title":"grammis: Wegen dem Regen oder wegen des Regens? Celownik czy dopełniacz","url":"https://grammis.ids-mannheim.de/fragen/67"},{"id":"weil","title":"słownik spójników grammis: weil (spójnik podrzędny przyczynowy, czasownik na końcu)","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"słownik spójników grammis: denn (spójnik przyczynowy, pozycja 0)","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"adverb","title":"grammis: Nicht nacherstfähige Adverbkonnektoren (deshalb, darum: pozycja 1 lub środek zdania)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/1279"},{"id":"deshalb","title":"słownik spójników grammis: deshalb (skutek; synonimy daher, deswegen)","url":"https://grammis.ids-mannheim.de/konnektoren/407094"},{"id":"deswegen","title":"słownik spójników grammis: deswegen (skutek; synonimy daher, deshalb)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"darum","title":"słownik spójników grammis: d(a)rum (skutek; inne użycie: darum jako dopełnienie z um)","url":"https://grammis.ids-mannheim.de/konnektoren/407096"},{"id":"korrelat","title":"grammis: Pronominaladverbien in Konnektorfunktion (deshalb/deswegen jako wskazanie na zdanie z weil)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/2602"},{"id":"dann","title":"słownik spójników grammis: dann (przysłówek czasu; partner zdań z wenn)","url":"https://grammis.ids-mannheim.de/konnektoren/406978"},{"id":"partikel","title":"grammis: Abtönungspartikeln (denn w pytaniach a spójnik denn)","url":"https://grammis.ids-mannheim.de/progr@mm/6856"},{"id":"duden-darum","title":"Duden: darum („aus diesem Grunde, deswegen, deshalb“; Darum! jako szorstka, potoczna odpowiedź)","url":"https://www.duden.de/rechtschreibung/darum"},{"id":"duden-dann","title":"Duden: dann (potem; w takim razie; jeśli … to)","url":"https://www.duden.de/rechtschreibung/dann"},{"id":"dereko","title":"IDS Mannheim: listy frekwencyjne DeReKo (deshalb około 1,7 miliona, deswegen około 0,3 miliona razy)","url":"https://www.ids-mannheim.de/digspra/kl/projekte/methoden/derewo/"}]}];
